export const VITAL_STATS_PORTAL_HTML: string = "<!DOCTYPE html>\n<html lang=\"en\" class=\"scroll-smooth\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>VitalStats | Clinical Supplement Analytics & Synthesis Portal</title>\n    <!-- Tailwind CSS -->\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <!-- Chart.js -->\n    <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n    <!-- FontAwesome Icons -->\n    <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\">\n    <!-- Google Fonts -->\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&family=JetBrains+Mono:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n    \n    <script>\n        tailwind.config = {\n            theme: {\n                extend: {\n                    fontFamily: {\n                        sans: ['\"Plus Jakarta Sans\"', 'sans-serif'],\n                        mono: ['\"JetBrains Mono\"', 'monospace']\n                    },\n                    colors: {\n                        brand: {\n                            50: '#ecfdf5',\n                            100: '#d1fae5',\n                            500: '#10b981',\n                            600: '#059669',\n                            700: '#047857',\n                            900: '#064e3b',\n                            950: '#022c22'\n                        }\n                    }\n                }\n            }\n        }\n    </script>\n    <style>\n        body { font-family: 'Plus Jakarta Sans', sans-serif; background-color: #0f172a; color: #f8fafc; }\n        .glass-panel { background: rgba(30, 41, 59, 0.75); backdrop-filter: blur(16px); border: 1px solid rgba(255, 255, 255, 0.08); }\n        .glass-card { background: rgba(15, 23, 42, 0.6); backdrop-filter: blur(12px); border: 1px solid rgba(255, 255, 255, 0.05); }\n        .tab-active { background-color: #059669; color: white; border-color: #10b981; }\n        .tab-inactive { background-color: rgba(30, 41, 59, 0.5); color: #94a3b8; border: 1px solid rgba(255, 255, 255, 0.1); }\n        .chart-container { position: relative; width: 100%; height: 380px; }\n        .chart-container-sm { position: relative; width: 100%; height: 280px; }\n        .custom-scrollbar::-webkit-scrollbar { width: 6px; height: 6px; }\n        .custom-scrollbar::-webkit-scrollbar-track { background: rgba(15, 23, 42, 0.5); }\n        .custom-scrollbar::-webkit-scrollbar-thumb { background: #334155; border-radius: 9999px; }\n        .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #059669; }\n        .amber-glow { box-shadow: 0 0 25px rgba(217, 119, 6, 0.2); }\n        .emerald-glow { box-shadow: 0 0 25px rgba(16, 185, 129, 0.2); }\n    </style>\n</head>\n<body class=\"antialiased selection:bg-brand-500 selection:text-white custom-scrollbar min-h-screen flex flex-col justify-between\">\n\n    <nav class=\"sticky top-0 z-40 glass-panel border-b border-slate-800/80 shadow-2xl\">\n        <div class=\"max-w-7xl mx-auto px-4 sm:px-6 lg:px-8\">\n            <div class=\"flex justify-between h-16 items-center\">\n                <div class=\"flex items-center gap-3\">\n                    <div class=\"w-10 h-10 bg-gradient-to-br from-brand-500 to-emerald-700 rounded-xl flex items-center justify-center text-white font-extrabold text-xl shadow-lg shadow-brand-500/30\">\n                        V\n                    </div>\n                    <div>\n                        <div class=\"flex items-center gap-2\">\n                            <span class=\"text-xl font-black tracking-tight text-white\">VitalStats</span>\n                            <span class=\"text-[10px] font-bold px-2 py-0.5 bg-brand-500/20 text-brand-400 border border-brand-500/30 rounded-full font-mono uppercase\">v4.2 Clinical</span>\n                        </div>\n                        <p class=\"text-[11px] text-slate-400 font-medium hidden sm:block\">Supplement Analytics & Systematic Research Portal</p>\n                    </div>\n                </div>\n\n                <div class=\"hidden xl:flex space-x-5 text-xs font-semibold tracking-wide uppercase\">\n                    <a href=\"#database\" class=\"text-slate-300 hover:text-brand-400 transition flex items-center gap-1.5\"><i class=\"fa-solid fa-database text-brand-500\"></i> Evidence Matrix</a>\n                    <a href=\"#assessment\" class=\"text-slate-300 hover:text-brand-400 transition flex items-center gap-1.5\"><i class=\"fa-solid fa-user-doctor text-emerald-400\"></i> Assessment Wizard</a>\n                    <a href=\"#rankings\" class=\"text-slate-300 hover:text-brand-400 transition flex items-center gap-1.5\"><i class=\"fa-solid fa-chart-bar text-cyan-400\"></i> NHANES Drivers</a>\n                    <a href=\"#athletics\" class=\"text-slate-300 hover:text-brand-400 transition flex items-center gap-1.5\"><i class=\"fa-solid fa-dumbbell text-amber-400\"></i> Athletics</a>\n                    <a href=\"#clinical-ed\" class=\"text-slate-300 hover:text-brand-400 transition flex items-center gap-1.5\"><i class=\"fa-solid fa-heart-pulse text-rose-400\"></i> ED & Androgens</a>\n                    <a href=\"#sentinel\" class=\"text-slate-300 hover:text-brand-400 transition flex items-center gap-1.5\"><i class=\"fa-solid fa-wave-square text-indigo-400\"></i> Microvascular Model</a>\n                    <a href=\"#adulteration\" class=\"text-slate-300 hover:text-brand-400 transition flex items-center gap-1.5\"><i class=\"fa-solid fa-shield-triangle-exclamation text-amber-500\"></i> Safety Audit</a>\n                </div>\n\n                <div class=\"flex items-center gap-3\">\n                    <button onclick=\"openModal('assessmentModal')\" class=\"px-4 py-2 text-xs font-bold bg-brand-600 hover:bg-brand-500 text-white rounded-xl shadow-lg shadow-brand-600/30 transition flex items-center gap-2\">\n                        <i class=\"fa-solid fa-calculator\"></i>\n                        <span>Rx Assessment</span>\n                    </button>\n                    <button id=\"mobileMenuBtn\" onclick=\"toggleMobileMenu()\" class=\"xl:hidden p-2 text-slate-400 hover:text-white text-lg\">\n                        <i class=\"fa-solid fa-bars\"></i>\n                    </button>\n                </div>\n            </div>\n        </div>\n\n        <!-- Mobile Menu Drawer -->\n        <div id=\"mobileMenu\" class=\"hidden xl:hidden bg-slate-900/95 border-b border-slate-800 px-4 py-4 space-y-3 text-xs font-semibold uppercase\">\n            <a href=\"#database\" onclick=\"toggleMobileMenu()\" class=\"block py-2 text-slate-300 hover:text-brand-400\"><i class=\"fa-solid fa-database mr-2 text-brand-500\"></i> Evidence Matrix</a>\n            <a href=\"#assessment\" onclick=\"toggleMobileMenu()\" class=\"block py-2 text-slate-300 hover:text-brand-400\"><i class=\"fa-solid fa-user-doctor mr-2 text-emerald-400\"></i> Assessment Wizard</a>\n            <a href=\"#rankings\" onclick=\"toggleMobileMenu()\" class=\"block py-2 text-slate-300 hover:text-brand-400\"><i class=\"fa-solid fa-chart-bar mr-2 text-cyan-400\"></i> NHANES Top 10</a>\n            <a href=\"#athletics\" onclick=\"toggleMobileMenu()\" class=\"block py-2 text-slate-300 hover:text-brand-400\"><i class=\"fa-solid fa-dumbbell mr-2 text-amber-400\"></i> Athletics & Muscle</a>\n            <a href=\"#clinical-ed\" onclick=\"toggleMobileMenu()\" class=\"block py-2 text-slate-300 hover:text-brand-400\"><i class=\"fa-solid fa-heart-pulse mr-2 text-rose-400\"></i> ED & Androgens</a>\n            <a href=\"#sentinel\" onclick=\"toggleMobileMenu()\" class=\"block py-2 text-slate-300 hover:text-brand-400\"><i class=\"fa-solid fa-wave-square mr-2 text-indigo-400\"></i> Microvascular Sentinel</a>\n            <a href=\"#adulteration\" onclick=\"toggleMobileMenu()\" class=\"block py-2 text-slate-300 hover:text-brand-400\"><i class=\"fa-solid fa-shield-triangle-exclamation mr-2 text-amber-500\"></i> Quality & Safety</a>\n        </div>\n    </nav>\n\n    <main class=\"max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-16\">\n        \n        <!-- Hero Section -->\n        <section class=\"relative overflow-hidden rounded-3xl bg-gradient-to-br from-slate-900 via-slate-950 to-slate-900 border border-slate-800 p-8 sm:p-12 shadow-2xl\">\n            <div class=\"absolute -right-20 -top-20 w-96 h-96 bg-brand-500/10 rounded-full blur-3xl pointer-events-none\"></div>\n            <div class=\"absolute -left-20 -bottom-20 w-96 h-96 bg-indigo-500/10 rounded-full blur-3xl pointer-events-none\"></div>\n\n            <div class=\"relative z-10 max-w-4xl space-y-6\">\n                <div class=\"inline-flex items-center gap-2 bg-slate-800/80 border border-brand-500/30 text-brand-300 text-xs font-bold px-3.5 py-1.5 rounded-full font-mono uppercase tracking-wider\">\n                    <span class=\"w-2 h-2 rounded-full bg-brand-400 animate-pulse\"></span>\n                    Epidemiological Surveillance & Meta-Analytic Synthesis\n                </div>\n\n                <h1 class=\"text-3xl sm:text-5xl font-black text-white leading-tight tracking-tight\">\n                    Clinical Dietary Supplement Matrix & Diagnostic Analytics\n                </h1>\n\n                <p class=\"text-slate-300 text-sm sm:text-base leading-relaxed max-w-3xl\">\n                    Integrating CDC NHANES surveillance data with systematic RCT meta-analyses to evaluate ergogenic efficacy, endocrine pathways (HPG/HPA axes), endothelial microvascular mechanisms, and regulatory adulteration risks.\n                </p>\n\n                <!-- Hero Executive KPIs -->\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-4 pt-4\">\n                    <div class=\"glass-card p-4 rounded-2xl border-l-4 border-brand-500\">\n                        <span class=\"block text-2xl sm:text-3xl font-black text-brand-400 font-mono\">57.6%</span>\n                        <span class=\"text-[11px] font-bold text-slate-400 uppercase tracking-wider\">NHANES Population Rate</span>\n                    </div>\n                    <div class=\"glass-card p-4 rounded-2xl border-l-4 border-cyan-500\">\n                        <span class=\"block text-2xl sm:text-3xl font-black text-cyan-400 font-mono\">73.1%</span>\n                        <span class=\"text-[11px] font-bold text-slate-400 uppercase tracking-wider\">Self-Initiated Care</span>\n                    </div>\n                    <div class=\"glass-card p-4 rounded-2xl border-l-4 border-amber-500\">\n                        <span class=\"block text-2xl sm:text-3xl font-black text-amber-400 font-mono\">45.5%</span>\n                        <span class=\"text-[11px] font-bold text-slate-400 uppercase tracking-wider\">FDA Tainted (Sexual)</span>\n                    </div>\n                    <div class=\"glass-card p-4 rounded-2xl border-l-4 border-emerald-500\">\n                        <span class=\"block text-2xl sm:text-3xl font-black text-emerald-400 font-mono\">97.0%</span>\n                        <span class=\"text-[11px] font-bold text-slate-400 uppercase tracking-wider\">Max Synergy SUCRA</span>\n                    </div>\n                </div>\n\n                <div class=\"flex flex-wrap gap-3 pt-2\">\n                    <a href=\"#assessment\" class=\"px-5 py-2.5 text-xs font-extrabold bg-brand-600 hover:bg-brand-500 text-white rounded-xl shadow-lg transition flex items-center gap-2\">\n                        <i class=\"fa-solid fa-sliders\"></i> Open Assessment Protocol\n                    </a>\n                    <a href=\"#database\" class=\"px-5 py-2.5 text-xs font-extrabold bg-slate-800 hover:bg-slate-700 text-slate-200 border border-slate-700 rounded-xl transition flex items-center gap-2\">\n                        <i class=\"fa-solid fa-magnifying-glass\"></i> Explore 15+ Clinical Matrix Compounds\n                    </a>\n                </div>\n            </div>\n        </section>\n\n        <!-- Interactive Supplement Database & Evidence Matrix Section -->\n        <section id=\"database\" class=\"space-y-6\">\n            <div class=\"flex flex-col md:flex-row md:items-end justify-between gap-4 border-b border-slate-800 pb-6\">\n                <div>\n                    <div class=\"inline-flex items-center gap-2 text-brand-400 text-xs font-mono font-bold uppercase tracking-wider mb-2\">\n                        <i class=\"fa-solid fa-layer-group\"></i> Dynamic Master Matrix\n                    </div>\n                    <h2 class=\"text-2xl sm:text-3xl font-extrabold text-white\">Clinical Supplement Evidence Database</h2>\n                    <p class=\"text-slate-400 text-xs sm:text-sm mt-1\">Search, filter, and inspect trial outcomes, target mechanisms, and clinical dosing guidelines.</p>\n                </div>\n\n                <!-- Controls -->\n                <div class=\"flex flex-wrap items-center gap-3\">\n                    <!-- Search Input -->\n                    <div class=\"relative\">\n                        <i class=\"fa-solid fa-magnifying-glass absolute left-3 top-1/2 -translate-y-1/2 text-slate-500 text-xs\"></i>\n                        <input type=\"text\" id=\"dbSearch\" oninput=\"filterDB()\" placeholder=\"Search compound or mechanism...\" class=\"bg-slate-900 border border-slate-700 rounded-xl pl-9 pr-4 py-2 text-xs text-white focus:outline-none focus:border-brand-500 w-60\">\n                    </div>\n                    <!-- Category Dropdown -->\n                    <select id=\"dbCategoryFilter\" onchange=\"filterDB()\" class=\"bg-slate-900 border border-slate-700 rounded-xl px-3 py-2 text-xs text-white focus:outline-none focus:border-brand-500\">\n                        <option value=\"all\">All Categories</option>\n                        <option value=\"Ergogenic\">Ergogenic & Muscle</option>\n                        <option value=\"Vascular / ED\">Vascular / Sexual Health</option>\n                        <option value=\"Endocrine / T-Booster\">Endocrine & Androgen</option>\n                        <option value=\"Micronutrient\">Micronutrients</option>\n                    </select>\n                    <!-- Grade Dropdown -->\n                    <select id=\"dbGradeFilter\" onchange=\"filterDB()\" class=\"bg-slate-900 border border-slate-700 rounded-xl px-3 py-2 text-xs text-white focus:outline-none focus:border-brand-500\">\n                        <option value=\"all\">All Evidence Grades</option>\n                        <option value=\"High\">High Grade</option>\n                        <option value=\"Moderate\">Moderate Grade</option>\n                        <option value=\"Preliminary\">Preliminary / Mixed</option>\n                        <option value=\"Caution\">Caution / Negative</option>\n                    </select>\n                </div>\n            </div>\n\n            <!-- Database Cards Grid -->\n            <div id=\"dbCardGrid\" class=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6\">\n                <!-- Injected via JavaScript -->\n            </div>\n        </section>\n\n        <!-- Interactive Assessment Protocol Wizard Section -->\n        <section id=\"assessment\" class=\"glass-panel rounded-3xl p-6 sm:p-10 border border-slate-800 shadow-2xl relative overflow-hidden space-y-8\">\n            <div class=\"flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 border-b border-slate-800 pb-6\">\n                <div>\n                    <span class=\"text-xs font-mono font-bold text-emerald-400 uppercase tracking-widest bg-emerald-500/10 px-3 py-1 rounded-full border border-emerald-500/20\">Clinical Protocol Wizard</span>\n                    <h2 class=\"text-2xl sm:text-3xl font-black text-white mt-2\">Personalized Supplement Assessment & Safety Protocol</h2>\n                    <p class=\"text-slate-400 text-xs sm:text-sm mt-1\">Enter profile parameters to evaluate evidence-backed interventions, dose calculations, and contraindication flags.</p>\n                </div>\n                <div class=\"flex items-center gap-2 text-xs font-mono bg-slate-900 px-4 py-2 rounded-xl border border-slate-800 text-slate-300\">\n                    <i class=\"fa-solid fa-shield-halved text-brand-400\"></i>\n                    <span>Evidence Level Checked</span>\n                </div>\n            </div>\n\n            <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-8\">\n                <!-- Form Inputs -->\n                <div class=\"lg:col-span-5 space-y-5 bg-slate-900/80 p-6 rounded-2xl border border-slate-800\">\n                    <h3 class=\"text-sm font-bold text-white uppercase tracking-wider flex items-center gap-2\">\n                        <i class=\"fa-solid fa-sliders text-brand-400\"></i> Baseline Inputs\n                    </h3>\n\n                    <!-- Target Goal -->\n                    <div>\n                        <label class=\"block text-xs font-bold text-slate-300 mb-2\">Primary Therapeutic Goal</label>\n                        <select id=\"wizardGoal\" onchange=\"calculateWizard()\" class=\"w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-xs text-white focus:outline-none focus:border-brand-500\">\n                            <option value=\"ed_vascular\">Erectile Function & Microvascular Support</option>\n                            <option value=\"testosterone\">Serum Testosterone Optimization (Hypogonadism/Stress)</option>\n                            <option value=\"hypertrophy\">Muscle Protein Synthesis & Ergogenic Power</option>\n                            <option value=\"general\">General Wellness & Micronutrient Repletion</option>\n                        </select>\n                    </div>\n\n                    <!-- Body Weight & Age -->\n                    <div class=\"grid grid-cols-2 gap-4\">\n                        <div>\n                            <label class=\"block text-xs font-bold text-slate-300 mb-1\">Body Weight (kg)</label>\n                            <input type=\"number\" id=\"wizardWeight\" value=\"80\" min=\"40\" max=\"160\" oninput=\"calculateWizard()\" class=\"w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-xs text-white focus:outline-none focus:border-brand-500 font-mono\">\n                        </div>\n                        <div>\n                            <label class=\"block text-xs font-bold text-slate-300 mb-1\">Age (Years)</label>\n                            <input type=\"number\" id=\"wizardAge\" value=\"38\" min=\"18\" max=\"90\" oninput=\"calculateWizard()\" class=\"w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-xs text-white focus:outline-none focus:border-brand-500 font-mono\">\n                        </div>\n                    </div>\n\n                    <!-- Clinical Status Checkboxes -->\n                    <div class=\"space-y-3 pt-2\">\n                        <label class=\"block text-xs font-bold text-slate-300\">Clinical Status & Prescription Flags</label>\n\n                        <label class=\"flex items-center gap-3 p-3 bg-slate-950/60 rounded-xl border border-slate-800/80 cursor-pointer hover:border-slate-700 transition\">\n                            <input type=\"checkbox\" id=\"wizardNitrates\" onchange=\"calculateWizard()\" class=\"rounded border-slate-700 text-brand-500 focus:ring-brand-500 bg-slate-900\">\n                            <div>\n                                <span class=\"text-xs font-bold text-rose-400 block\">Taking Prescription Nitrates / Nitroglycerin</span>\n                                <span class=\"text-[10px] text-slate-400\">Triggers severe refractory hypotension alert with PDE5/adulterants.</span>\n                            </div>\n                        </label>\n\n                        <label class=\"flex items-center gap-3 p-3 bg-slate-950/60 rounded-xl border border-slate-800/80 cursor-pointer hover:border-slate-700 transition\">\n                            <input type=\"checkbox\" id=\"wizardStressed\" onchange=\"calculateWizard()\" class=\"rounded border-slate-700 text-brand-500 focus:ring-brand-500 bg-slate-900\">\n                            <div>\n                                <span class=\"text-xs font-bold text-slate-200 block\">Chronic Stress / Elevated Baseline Cortisol</span>\n                                <span class=\"text-[10px] text-slate-400\">Indicates HPA-axis targeting adaptogens (Ashwagandha KSM-66).</span>\n                            </div>\n                        </label>\n\n                        <label class=\"flex items-center gap-3 p-3 bg-slate-950/60 rounded-xl border border-slate-800/80 cursor-pointer hover:border-slate-700 transition\">\n                            <input type=\"checkbox\" id=\"wizardTrained\" onchange=\"calculateWizard()\" class=\"rounded border-slate-700 text-brand-500 focus:ring-brand-500 bg-slate-900\" checked>\n                            <div>\n                                <span class=\"text-xs font-bold text-slate-200 block\">Resistance Trained / Intense Exercise Cohort</span>\n                                <span class=\"text-[10px] text-slate-400\">Alters D-Aspartic Acid feedback and Creatine saturation protocols.</span>\n                            </div>\n                        </label>\n\n                        <label class=\"flex items-center gap-3 p-3 bg-slate-950/60 rounded-xl border border-slate-800/80 cursor-pointer hover:border-slate-700 transition\">\n                            <input type=\"checkbox\" id=\"wizardDeficient\" onchange=\"calculateWizard()\" class=\"rounded border-slate-700 text-brand-500 focus:ring-brand-500 bg-slate-900\">\n                            <div>\n                                <span class=\"text-xs font-bold text-slate-200 block\">Confirmed Zinc or Vitamin D Deficiency</span>\n                                <span class=\"text-[10px] text-slate-400\">Required substrate for enzymatic 17β-HSD androgen production.</span>\n                            </div>\n                        </label>\n                    </div>\n                </div>\n\n                <!-- Wizard Recommendation Results -->\n                <div class=\"lg:col-span-7 flex flex-col justify-between space-y-6\">\n                    <div>\n                        <div class=\"flex items-center justify-between mb-4\">\n                            <h3 class=\"text-sm font-bold text-white uppercase tracking-wider flex items-center gap-2\">\n                                <i class=\"fa-solid fa-list-check text-emerald-400\"></i> Evidence-Based Recommendation Protocol\n                            </h3>\n                            <button onclick=\"copyProtocolText()\" class=\"text-xs font-mono text-brand-400 hover:text-brand-300 flex items-center gap-1.5 bg-brand-500/10 px-3 py-1 rounded-lg border border-brand-500/20\">\n                                <i class=\"fa-solid fa-copy\"></i> Copy Protocol\n                            </button>\n                        </div>\n\n                        <!-- Safety Warnings Container -->\n                        <div id=\"wizardWarningsContainer\" class=\"space-y-3 mb-4\">\n                            <!-- Injected dynamically -->\n                        </div>\n\n                        <!-- Recommendations Cards Stack -->\n                        <div id=\"wizardRecommendationsContainer\" class=\"space-y-3\">\n                            <!-- Injected dynamically -->\n                        </div>\n                    </div>\n\n                    <div class=\"p-4 bg-slate-900/60 rounded-2xl border border-slate-800 text-xs text-slate-400 leading-relaxed font-mono\">\n                        <i class=\"fa-solid fa-circle-info text-cyan-400 mr-1.5\"></i>\n                        <span>Protocol dosing calculated based on clinical trial weight standardization. Always confirm lab markers with a healthcare provider before initiating high-dose nutraceutical stacks.</span>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <!-- NHANES Top 10 Motivations & Demographics Section -->\n        <section id=\"rankings\" class=\"space-y-8\">\n            <div class=\"text-center max-w-3xl mx-auto space-y-3\">\n                <div class=\"inline-flex items-center gap-2 text-cyan-400 text-xs font-mono font-bold uppercase tracking-wider bg-cyan-500/10 px-3.5 py-1 rounded-full border border-cyan-500/20\">\n                    CDC NHANES Surveillance Analysis\n                </div>\n                <h2 class=\"text-3xl font-extrabold text-white\">Top 10 Motivations for Supplement Usage</h2>\n                <p class=\"text-slate-400 text-xs sm:text-sm leading-relaxed\">\n                    Surveillance data reveals clear sex-disaggregated divergences. While overall health maintenance predominates, target motivations vary significantly across male and female populations.\n                </p>\n            </div>\n\n            <div class=\"glass-panel p-6 sm:p-8 rounded-3xl border border-slate-800 space-y-8\">\n                <!-- Toggle Tab Buttons -->\n                <div class=\"flex justify-center gap-3\">\n                    <button onclick=\"updateMotivationsChart('overall')\" id=\"btn-overall\" class=\"px-5 py-2 rounded-full text-xs font-bold uppercase tracking-wider transition tab-active\">Overall Population</button>\n                    <button onclick=\"updateMotivationsChart('male')\" id=\"btn-male\" class=\"px-5 py-2 rounded-full text-xs font-bold uppercase tracking-wider transition tab-inactive\">Male Cohort</button>\n                    <button onclick=\"updateMotivationsChart('female')\" id=\"btn-female\" class=\"px-5 py-2 rounded-full text-xs font-bold uppercase tracking-wider transition tab-inactive\">Female Cohort</button>\n                </div>\n\n                <!-- Main Bar Chart -->\n                <div class=\"chart-container\">\n                    <canvas id=\"motivationsChart\"></canvas>\n                </div>\n\n                <!-- Rank Cards Display Grid -->\n                <div id=\"topListDisplay\" class=\"grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-4 pt-4\">\n                    <!-- Cards injected via JS -->\n                </div>\n            </div>\n\n            <!-- Demographics & Healthy User Bias Grid -->\n            <div class=\"grid grid-cols-1 lg:grid-cols-2 gap-8 items-stretch\">\n                <!-- Age Chart Panel -->\n                <div class=\"glass-panel p-6 sm:p-8 rounded-3xl border border-slate-800 flex flex-col justify-between\">\n                    <div>\n                        <h3 class=\"text-xl font-bold text-white mb-2\">Age Stratification Gradient</h3>\n                        <p class=\"text-slate-400 text-xs mb-6\">Supplement consumption follows a linear progression with advancing age, exceeding 71% in adults aged 60+.</p>\n                    </div>\n                    <div class=\"chart-container-sm\">\n                        <canvas id=\"ageChart\"></canvas>\n                    </div>\n                </div>\n\n                <!-- Socioeconomic Bias Panel -->\n                <div class=\"glass-panel p-6 sm:p-8 rounded-3xl border border-slate-800 flex flex-col justify-between space-y-6\">\n                    <div>\n                        <div class=\"inline-flex items-center gap-2 text-amber-400 text-xs font-mono font-bold uppercase tracking-wider mb-2\">\n                            Epidemiological Bias\n                        </div>\n                        <h3 class=\"text-xl font-bold text-white mb-2\">The \"Healthy User Bias\" Paradox</h3>\n                        <p class=\"text-slate-400 text-xs leading-relaxed\">\n                            Data indicates an inverse relationship between nutritional need and supplement usage. Populations with higher educational attainment and healthiest baseline lifestyles consume the largest volume of supplements.\n                        </p>\n                    </div>\n\n                    <div class=\"space-y-4\">\n                        <div class=\"p-4 bg-slate-900/80 rounded-2xl border-l-4 border-emerald-500 border border-slate-800\">\n                            <div class=\"flex justify-between items-center mb-1\">\n                                <span class=\"font-bold text-white text-xs\">College Graduate Prevalence</span>\n                                <span class=\"font-mono text-brand-400 font-extrabold text-sm\">58.2%</span>\n                            </div>\n                            <p class=\"text-[11px] text-slate-400\">Vs. 16.5% prevalence among non-high school graduates.</p>\n                        </div>\n\n                        <div class=\"p-4 bg-slate-900/80 rounded-2xl border-l-4 border-cyan-500 border border-slate-800\">\n                            <div class=\"flex justify-between items-center mb-1\">\n                                <span class=\"font-bold text-white text-xs\">Active Exercise & Non-Smoker Cohort</span>\n                                <span class=\"font-mono text-cyan-400 font-extrabold text-sm\">73.1%</span>\n                            </div>\n                            <p class=\"text-[11px] text-slate-400\">Regular exercisers constitute the majority of daily multi-vitamin consumers.</p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <!-- Athletic Performance & Male Ergogenic Aids Section -->\n        <section id=\"athletics\" class=\"space-y-8\">\n            <div class=\"text-center max-w-3xl mx-auto space-y-3\">\n                <div class=\"inline-flex items-center gap-2 text-amber-400 text-xs font-mono font-bold uppercase tracking-wider bg-amber-500/10 px-3.5 py-1 rounded-full border border-amber-500/20\">\n                    Ergogenic Aids & Sports Science\n                </div>\n                <h2 class=\"text-3xl font-extrabold text-white\">Athletic Performance & Male Muscle Growth</h2>\n                <p class=\"text-slate-400 text-xs sm:text-sm leading-relaxed\">\n                    Ergogenic drivers prioritize rapid phosphocreatine replenishment, mTOR pathway stimulation, eNOS hyperemia, and neuromuscular acid buffering.\n                </p>\n            </div>\n\n            <!-- KPI Metric Strip -->\n            <div class=\"grid grid-cols-2 md:grid-cols-4 gap-4\">\n                <div class=\"glass-card p-5 rounded-2xl border border-slate-800 text-center\">\n                    <span class=\"block text-3xl font-black text-amber-400 font-mono mb-1\">68%</span>\n                    <span class=\"text-[11px] font-bold text-slate-300 uppercase tracking-wider block\">Young Active Males</span>\n                    <p class=\"text-[10px] text-slate-500 mt-1\">Consume protein powders post-workout</p>\n                </div>\n                <div class=\"glass-card p-5 rounded-2xl border border-slate-800 text-center\">\n                    <span class=\"block text-3xl font-black text-white font-mono mb-1\">3.2x</span>\n                    <span class=\"text-[11px] font-bold text-slate-300 uppercase tracking-wider block\">Ergogenic Priority</span>\n                    <p class=\"text-[10px] text-slate-500 mt-1\">Males &lt;40 prioritize athletic goals vs general health</p>\n                </div>\n                <div class=\"glass-card p-5 rounded-2xl border border-slate-800 text-center\">\n                    <span class=\"block text-3xl font-black text-brand-400 font-mono mb-1\">45%</span>\n                    <span class=\"text-[11px] font-bold text-slate-300 uppercase tracking-wider block\">Creatine Monohydrate</span>\n                    <p class=\"text-[10px] text-slate-500 mt-1\">Uptake among strength-training males</p>\n                </div>\n                <div class=\"glass-card p-5 rounded-2xl border border-slate-800 text-center\">\n                    <span class=\"block text-3xl font-black text-cyan-400 font-mono mb-1\">82%</span>\n                    <span class=\"text-[11px] font-bold text-slate-300 uppercase tracking-wider block\">DOMS Recovery Focus</span>\n                    <p class=\"text-[10px] text-slate-500 mt-1\">Report supplementing specifically for muscle repair</p>\n                </div>\n            </div>\n\n            <!-- Three Pillars Grid -->\n            <div class=\"grid grid-cols-1 md:grid-cols-3 gap-6\">\n                <div class=\"glass-panel p-6 sm:p-8 rounded-3xl border border-slate-800 flex flex-col justify-between space-y-6\">\n                    <div>\n                        <div class=\"w-10 h-10 bg-amber-500/20 text-amber-400 rounded-xl flex items-center justify-center font-bold text-base mb-4 border border-amber-500/30\">01</div>\n                        <h3 class=\"text-xl font-bold text-white mb-2\">Hypertrophy & MPS</h3>\n                        <p class=\"text-slate-400 text-xs mb-4 leading-relaxed\">Triggers mTORC1 signaling via high leucine thresholds and accelerates intra-muscular phosphocreatine regeneration.</p>\n                        <ul class=\"space-y-2.5 text-xs text-slate-300\">\n                            <li class=\"flex items-center gap-2\"><i class=\"fa-solid fa-check text-brand-400\"></i><strong>Whey Isolate:</strong> Fast-digesting EAAs (3g Leucine/dose)</li>\n                            <li class=\"flex items-center gap-2\"><i class=\"fa-solid fa-check text-brand-400\"></i><strong>Creatine Monohydrate:</strong> 3-5g daily cell volumization</li>\n                            <li class=\"flex items-center gap-2\"><i class=\"fa-solid fa-check text-brand-400\"></i><strong>EAAs:</strong> Intra-workout muscle protein sparing</li>\n                        </ul>\n                    </div>\n                </div>\n\n                <div class=\"glass-panel p-6 sm:p-8 rounded-3xl border border-slate-800 flex flex-col justify-between space-y-6\">\n                    <div>\n                        <div class=\"w-10 h-10 bg-brand-500/20 text-brand-400 rounded-xl flex items-center justify-center font-bold text-base mb-4 border border-brand-500/30\">02</div>\n                        <h3 class=\"text-xl font-bold text-white mb-2\">Vaso-Pump & Acid Buffer</h3>\n                        <p class=\"text-slate-400 text-xs mb-4 leading-relaxed\">Delays neuromuscular fatigue, stimulates eNOS hyperemic vasodilation, and buffers intramuscular H+ accumulation.</p>\n                        <ul class=\"space-y-2.5 text-xs text-slate-300\">\n                            <li class=\"flex items-center gap-2\"><i class=\"fa-solid fa-check text-emerald-400\"></i><strong>L-Citrulline Malate:</strong> 6-8g daily nitric oxide output</li>\n                            <li class=\"flex items-center gap-2\"><i class=\"fa-solid fa-check text-emerald-400\"></i><strong>Beta-Alanine:</strong> 3.2-6.4g carnosine buffer</li>\n                            <li class=\"flex items-center gap-2\"><i class=\"fa-solid fa-check text-emerald-400\"></i><strong>Anhydrous Caffeine:</strong> Central nervous exertion reduction</li>\n                        </ul>\n                    </div>\n                </div>\n\n                <div class=\"glass-panel p-6 sm:p-8 rounded-3xl border border-slate-800 flex flex-col justify-between space-y-6\">\n                    <div>\n                        <div class=\"w-10 h-10 bg-cyan-500/20 text-cyan-400 rounded-xl flex items-center justify-center font-bold text-base mb-4 border border-cyan-500/30\">03</div>\n                        <h3 class=\"text-xl font-bold text-white mb-2\">Hormonal & Joint Recovery</h3>\n                        <p class=\"text-slate-400 text-xs mb-4 leading-relaxed\">Attenuates exercise-induced cortisol spikes, protects Leydig cell synthesis, and mitigates systemic joint inflammation.</p>\n                        <ul class=\"space-y-2.5 text-xs text-slate-300\">\n                            <li class=\"flex items-center gap-2\"><i class=\"fa-solid fa-check text-cyan-400\"></i><strong>Ashwagandha KSM-66:</strong> 600mg cortisol reduction</li>\n                            <li class=\"flex items-center gap-2\"><i class=\"fa-solid fa-check text-cyan-400\"></i><strong>Zinc & Mg (ZMA):</strong> Enzymatic steroidogenesis substrates</li>\n                            <li class=\"flex items-center gap-2\"><i class=\"fa-solid fa-check text-cyan-400\"></i><strong>Omega-3 EPA/DHA:</strong> Resolves microvascular joint inflammation</li>\n                        </ul>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <!-- Clinical Interventions for ED & Testosterone Synthesis Section -->\n        <section id=\"clinical-ed\" class=\"space-y-8\">\n            <div class=\"text-center max-w-3xl mx-auto space-y-3\">\n                <div class=\"inline-flex items-center gap-2 text-rose-400 text-xs font-mono font-bold uppercase tracking-wider bg-rose-500/10 px-3.5 py-1 rounded-full border border-rose-500/20\">\n                    Systematic RCT Synthesis\n                </div>\n                <h2 class=\"text-3xl font-extrabold text-white\">Erectile Dysfunction & Endocrine Modulation</h2>\n                <p class=\"text-slate-400 text-xs sm:text-sm leading-relaxed\">\n                    Evaluating botanical and nutraceutical agents targeting endothelial eNOS/cGMP pathways and HPG-axis Leydig cell steroidogenesis.\n                </p>\n            </div>\n\n            <!-- Botanical Interventions Table -->\n            <div class=\"glass-panel rounded-3xl border border-slate-800 overflow-hidden shadow-2xl\">\n                <div class=\"bg-slate-900/90 p-5 sm:p-6 border-b border-slate-800 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4\">\n                    <div>\n                        <h3 class=\"text-lg font-bold text-white flex items-center gap-2\">\n                            <i class=\"fa-solid fa-capsules text-brand-400\"></i> Vascular & Botanical Interventions for Erectile Dysfunction\n                        </h3>\n                        <p class=\"text-slate-400 text-xs mt-0.5\">Evaluated across randomized controlled trials (RCTs) and IIEF score improvements.</p>\n                    </div>\n                    <span class=\"text-xs bg-brand-500/10 text-brand-300 border border-brand-500/30 px-3 py-1 rounded-full font-mono\">eNOS / NO / cGMP Target</span>\n                </div>\n\n                <div class=\"overflow-x-auto\">\n                    <table class=\"w-full text-left text-xs sm:text-sm\">\n                        <thead class=\"bg-slate-950 text-slate-400 font-mono text-[11px] uppercase tracking-wider border-b border-slate-800\">\n                            <tr>\n                                <th class=\"p-4\">Nutraceutical Agent</th>\n                                <th class=\"p-4\">Active Bioactives</th>\n                                <th class=\"p-4\">Evaluated Daily Dose</th>\n                                <th class=\"p-4\">Meta-Analytic Clinical Outcome</th>\n                                <th class=\"p-4\">Evidence Grade</th>\n                            </tr>\n                        </thead>\n                        <tbody class=\"divide-y divide-slate-800/60 text-slate-300\">\n                            <tr class=\"hover:bg-slate-800/40 transition\">\n                                <td class=\"p-4 font-bold text-white\">Panax Ginseng</td>\n                                <td class=\"p-4\">Ginsenosides (Rb1, Rg1)</td>\n                                <td class=\"p-4 font-mono text-xs\">900 – 3000 mg/day</td>\n                                <td class=\"p-4\">Significant IIEF score increase (SMD 0.43 to 0.65; p &lt; 0.001) <button onclick=\"showCitationModal(5)\" class=\"text-brand-400 hover:underline font-mono ml-1\">[5,11]</button></td>\n                                <td class=\"p-4\"><span class=\"px-2.5 py-1 bg-brand-500/20 text-brand-300 border border-brand-500/30 rounded-lg text-xs font-bold\">High (Low-Risk RCTs)</span></td>\n                            </tr>\n                            <tr class=\"hover:bg-slate-800/40 transition\">\n                                <td class=\"p-4 font-bold text-white\">L-Arginine</td>\n                                <td class=\"p-4\">Free Amino Acid Substrate</td>\n                                <td class=\"p-4 font-mono text-xs\">1500 – 5000 mg/day</td>\n                                <td class=\"p-4\">Significant ED improvement (RR 1.48; 95% CI 1.17–1.87) <button onclick=\"showCitationModal(9)\" class=\"text-brand-400 hover:underline font-mono ml-1\">[9]</button></td>\n                                <td class=\"p-4\"><span class=\"px-2.5 py-1 bg-brand-500/20 text-brand-300 border border-brand-500/30 rounded-lg text-xs font-bold\">Mod-High (10 RCTs)</span></td>\n                            </tr>\n                            <tr class=\"hover:bg-slate-800/40 transition\">\n                                <td class=\"p-4 font-bold text-white\">Saffron (Crocus sativus)</td>\n                                <td class=\"p-4\">Crocin, Safranal</td>\n                                <td class=\"p-4 font-mono text-xs\">30 mg/day</td>\n                                <td class=\"p-4\">Improved erectile & orgasmic domain scores vs placebo <button onclick=\"showCitationModal(12)\" class=\"text-brand-400 hover:underline font-mono ml-1\">[5,12]</button></td>\n                                <td class=\"p-4\"><span class=\"px-2.5 py-1 bg-cyan-500/20 text-cyan-300 border border-cyan-500/30 rounded-lg text-xs font-bold\">Moderate (Multiple RCTs)</span></td>\n                            </tr>\n                            <tr class=\"hover:bg-slate-800/40 transition\">\n                                <td class=\"p-4 font-bold text-white\">French Maritime Pine Bark</td>\n                                <td class=\"p-4\">Oligomeric Proanthocyanidins</td>\n                                <td class=\"p-4 font-mono text-xs\">120 mg/day</td>\n                                <td class=\"p-4\">Synergistic eNOS activation when paired with L-arginine <button onclick=\"showCitationModal(5)\" class=\"text-brand-400 hover:underline font-mono ml-1\">[5]</button></td>\n                                <td class=\"p-4\"><span class=\"px-2.5 py-1 bg-amber-500/20 text-amber-300 border border-amber-500/30 rounded-lg text-xs font-bold\">Preliminary / Promising</span></td>\n                            </tr>\n                            <tr class=\"hover:bg-slate-800/40 transition\">\n                                <td class=\"p-4 font-bold text-white\">Tribulus terrestris</td>\n                                <td class=\"p-4\">Protodioscin Saponins</td>\n                                <td class=\"p-4 font-mono text-xs\">750 – 1500 mg/day</td>\n                                <td class=\"p-4\">Mixed, clinically non-significant monotherapy ED outcomes <button onclick=\"showCitationModal(5)\" class=\"text-brand-400 hover:underline font-mono ml-1\">[5]</button></td>\n                                <td class=\"p-4\"><span class=\"px-2.5 py-1 bg-slate-700 text-slate-300 rounded-lg text-xs font-bold\">Insufficient Evidence</span></td>\n                            </tr>\n                            <tr class=\"hover:bg-slate-800/40 transition\">\n                                <td class=\"p-4 font-bold text-white\">Maca (Lepidium meyenii)</td>\n                                <td class=\"p-4\">Macamides & Macaenes</td>\n                                <td class=\"p-4 font-mono text-xs\">1500 – 3000 mg/day</td>\n                                <td class=\"p-4\">Modest subjective libido; negligible impact on erection mechanics <button onclick=\"showCitationModal(5)\" class=\"text-brand-400 hover:underline font-mono ml-1\">[5]</button></td>\n                                <td class=\"p-4\"><span class=\"px-2.5 py-1 bg-slate-700 text-slate-300 rounded-lg text-xs font-bold\">Insufficient for ED</span></td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n            </div>\n\n            <!-- Endocrine Table & DAA Paradox Callout -->\n            <div class=\"glass-panel rounded-3xl border border-slate-800 overflow-hidden shadow-2xl\">\n                <div class=\"bg-slate-900/90 p-5 sm:p-6 border-b border-slate-800 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4\">\n                    <div>\n                        <h3 class=\"text-lg font-bold text-white flex items-center gap-2\">\n                            <i class=\"fa-solid fa-dna text-indigo-400\"></i> Endocrine Modulation & Serum Testosterone Synthesis\n                        </h3>\n                        <p class=\"text-slate-400 text-xs mt-0.5\">Hormonal shifts evaluated across baseline eugonadal vs hypogonadal/stressed cohorts.</p>\n                    </div>\n                    <span class=\"text-xs bg-indigo-500/10 text-indigo-300 border border-indigo-500/30 px-3 py-1 rounded-full font-mono\">HPG Axis / StAR Target</span>\n                </div>\n\n                <div class=\"overflow-x-auto\">\n                    <table class=\"w-full text-left text-xs sm:text-sm\">\n                        <thead class=\"bg-slate-950 text-slate-400 font-mono text-[11px] uppercase tracking-wider border-b border-slate-800\">\n                            <tr>\n                                <th class=\"p-4\">Supplement Compound</th>\n                                <th class=\"p-4\">Primary Target Mechanism</th>\n                                <th class=\"p-4\">Evaluated Daily Dose</th>\n                                <th class=\"p-4\">Serum Testosterone Outcome</th>\n                                <th class=\"p-4\">Target Cohort Efficacy</th>\n                            </tr>\n                        </thead>\n                        <tbody class=\"divide-y divide-slate-800/60 text-slate-300\">\n                            <tr class=\"hover:bg-slate-800/40 transition\">\n                                <td class=\"p-4 font-bold text-white\">Ashwagandha (KSM-66)</td>\n                                <td class=\"p-4\">HPA axis cortisol attenuation; Leydig protection</td>\n                                <td class=\"p-4 font-mono text-xs\">600 mg/day (300mg bid)</td>\n                                <td class=\"p-4\"><span class=\"font-bold text-brand-400\">+14.7% to +16.7%</span> total T increase (+167 ng/dL in lifters) <button onclick=\"showCitationModal(2)\" class=\"text-brand-400 hover:underline font-mono ml-1\">[2]</button></td>\n                                <td class=\"p-4 text-xs font-semibold text-slate-300\">Stressed, sedentary, or resistance-trained males</td>\n                            </tr>\n                            <tr class=\"hover:bg-slate-800/40 transition\">\n                                <td class=\"p-4 font-bold text-white\">Fenugreek (Testofen)</td>\n                                <td class=\"p-4\">Dual 5α-reductase & aromatase inhibition</td>\n                                <td class=\"p-4 font-mono text-xs\">500 – 600 mg/day</td>\n                                <td class=\"p-4\"><span class=\"font-bold text-brand-400\">Up to +46% free T</span> in 90% of trial participants <button onclick=\"showCitationModal(1)\" class=\"text-brand-400 hover:underline font-mono ml-1\">[1]</button></td>\n                                <td class=\"p-4 text-xs font-semibold text-slate-300\">Aging men with declining free bioavailable testosterone</td>\n                            </tr>\n                            <tr class=\"hover:bg-slate-800/40 transition\">\n                                <td class=\"p-4 font-bold text-white\">Tongkat Ali (Physta)</td>\n                                <td class=\"p-4\">SHBG reduction & Leydig cell steroidogenesis</td>\n                                <td class=\"p-4 font-mono text-xs\">200 – 600 mg/day</td>\n                                <td class=\"p-4\"><span class=\"font-bold text-brand-400\">+37% total T</span> in hypogonadal men; modest in athletes <button onclick=\"showCitationModal(2)\" class=\"text-brand-400 hover:underline font-mono ml-1\">[2]</button></td>\n                                <td class=\"p-4 text-xs font-semibold text-slate-300\">Mildly hypogonadal or chronically stressed men</td>\n                            </tr>\n                            <tr class=\"hover:bg-slate-800/40 transition\">\n                                <td class=\"p-4 font-bold text-white\">Zinc (Picolinate)</td>\n                                <td class=\"p-4\">17β-HSD enzymatic cofactor substrate</td>\n                                <td class=\"p-4 font-mono text-xs\">15 – 30 mg elemental</td>\n                                <td class=\"p-4\">Normalizes depressed T in deficient men; neutral in replete men <button onclick=\"showCitationModal(19)\" class=\"text-brand-400 hover:underline font-mono ml-1\">[19]</button></td>\n                                <td class=\"p-4 text-xs font-semibold text-slate-300\">Men with confirmed nutritional zinc deficiency</td>\n                            </tr>\n                            <tr class=\"hover:bg-slate-800/40 transition\">\n                                <td class=\"p-4 font-bold text-white\">Vitamin D3</td>\n                                <td class=\"p-4\">Leydig nuclear receptor activation</td>\n                                <td class=\"p-4 font-mono text-xs\">3000 – 5000 IU/day</td>\n                                <td class=\"p-4\">Modest elevation (+20%) if baseline &lt;20 ng/mL; neutral if replete <button onclick=\"showCitationModal(2)\" class=\"text-brand-400 hover:underline font-mono ml-1\">[2]</button></td>\n                                <td class=\"p-4 text-xs font-semibold text-slate-300\">Men with confirmed hypovitaminosis D</td>\n                            </tr>\n                            <tr class=\"bg-rose-950/30 hover:bg-rose-950/50 transition border-l-4 border-rose-500\">\n                                <td class=\"p-4 font-bold text-rose-300\">\n                                    D-Aspartic Acid (DAA) \n                                    <span class=\"block text-[10px] text-rose-400 uppercase font-mono font-bold mt-0.5\"><i class=\"fa-solid fa-triangle-exclamation mr-1\"></i> The DAA Paradox</span>\n                                </td>\n                                <td class=\"p-4 text-slate-300\">Hypothalamic GnRH / LH acute stimulation</td>\n                                <td class=\"p-4 font-mono text-xs text-rose-300\">3g vs 6g / day</td>\n                                <td class=\"p-4 font-bold text-rose-400\">\n                                    Neutral at 3g; <span class=\"underline\">12.5% DECREASE</span> in total T at 6g/day \n                                    <button onclick=\"showCitationModal(21)\" class=\"text-rose-400 hover:underline font-mono ml-1\">[21,23]</button>\n                                </td>\n                                <td class=\"p-4 text-xs font-bold text-rose-300\">\n                                    NOT RECOMMENDED for resistance-trained men (Triggers DDO enzymatic feedback)\n                                </td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n            </div>\n\n            <!-- SUCRA Chart & Synergy Analysis -->\n            <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-8 items-center\">\n                <div class=\"lg:col-span-5 glass-panel p-6 sm:p-8 rounded-3xl border border-slate-800 flex flex-col justify-between space-y-4\">\n                    <div>\n                        <div class=\"inline-flex items-center gap-2 bg-brand-500/10 border border-brand-500/20 text-brand-300 text-[10px] font-mono font-bold px-3 py-1 rounded-full uppercase tracking-wider mb-4\">\n                            Network Meta-Analysis (NMA)\n                        </div>\n                        <h3 class=\"text-2xl font-extrabold text-white\">Pharmacotherapy Synergy & Combination Protocols</h3>\n                        <p class=\"text-slate-300 text-xs leading-relaxed mt-3\">\n                            When evaluating Surface Under the Cumulative Ranking Curve (SUCRA) metrics, combining nitric oxide precursor amino acids (L-Arginine, Carnitines) with prescription PDE5 inhibitors yields higher therapeutic efficacy than PDE5 monotherapy alone in organic vascular ED.\n                        </p>\n                    </div>\n\n                    <div class=\"p-4 bg-slate-900/90 rounded-2xl border border-slate-800 text-xs text-slate-300 space-y-2 font-mono\">\n                        <p><strong class=\"text-brand-400\">Mechanism of Synergy:</strong> Amino acid donors expand eNOS substrate availability, elevating baseline cGMP production so PDE5 inhibitors have a greater substrate volume to protect from degradation.</p>\n                    </div>\n                </div>\n\n                <div class=\"lg:col-span-7 glass-panel p-6 sm:p-8 rounded-3xl border border-slate-800\">\n                    <h4 class=\"text-base font-bold text-white mb-1\">SUCRA Comparative Efficacy Ranking in Organic ED</h4>\n                    <p class=\"text-xs text-slate-400 mb-6\">Comparative ranking percentage based on IIEF score improvements across treatment arms [10].</p>\n                    <div class=\"chart-container-sm\">\n                        <canvas id=\"sucraChart\"></canvas>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <!-- Interactive Penile Artery Microvascular Sentinel Simulator -->\n        <section id=\"sentinel\" class=\"glass-panel p-6 sm:p-10 rounded-3xl border border-slate-800 space-y-8\">\n            <div class=\"flex flex-col md:flex-row justify-between items-start md:items-center gap-4 border-b border-slate-800 pb-6\">\n                <div>\n                    <span class=\"text-xs font-mono font-bold text-indigo-400 uppercase tracking-widest bg-indigo-500/10 px-3 py-1 rounded-full border border-indigo-500/20\">Cardiovascular Sentinel Concept</span>\n                    <h2 class=\"text-2xl sm:text-3xl font-black text-white mt-2\">The Penile Artery as an Early Cardiovascular Indicator</h2>\n                    <p class=\"text-slate-400 text-xs sm:text-sm mt-1\">Interactive lumen diameter simulation illustrating why vascular ED precedes Major Adverse Cardiovascular Events (MACE) by 2 to 5 years.</p>\n                </div>\n                <div class=\"text-xs font-mono bg-slate-900 px-4 py-2 rounded-xl border border-slate-800 text-slate-300\">\n                    <i class=\"fa-solid fa-heart-circle-bolt text-rose-400 mr-2\"></i>\n                    <span>Microvascular Caliber Delta</span>\n                </div>\n            </div>\n\n            <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-8 items-center\">\n                <!-- Simulation Canvas Side -->\n                <div class=\"lg:col-span-7 space-y-4\">\n                    <div class=\"bg-slate-950 p-4 rounded-2xl border border-slate-800 relative\">\n                        <div class=\"flex justify-between items-center mb-3\">\n                            <span class=\"text-xs font-mono font-bold text-slate-300\">Arterial Vessel Cross-Section Simulation</span>\n                            <span id=\"occlusionLabel\" class=\"text-xs font-mono font-bold text-amber-400\">Plaque Thickness: 0.50 mm</span>\n                        </div>\n                        <canvas id=\"sentinelCanvas\" class=\"w-full h-64 bg-slate-900 rounded-xl\"></canvas>\n                    </div>\n\n                    <!-- Interactive Slider Control -->\n                    <div class=\"space-y-2 bg-slate-900/80 p-4 rounded-xl border border-slate-800\">\n                        <div class=\"flex justify-between text-xs font-bold text-slate-300\">\n                            <span>Atherosclerotic Plaque Accumulation</span>\n                            <span id=\"sliderVal\" class=\"font-mono text-brand-400\">0.50 mm</span>\n                        </div>\n                        <input type=\"range\" id=\"plaqueSlider\" min=\"0\" max=\"1.4\" step=\"0.05\" value=\"0.5\" oninput=\"drawSentinelCanvas()\" class=\"w-full accent-brand-500 cursor-pointer\">\n                        <div class=\"flex justify-between text-[10px] font-mono text-slate-500\">\n                            <span>0.0mm (Healthy Lumen)</span>\n                            <span>0.7mm (Subclinical)</span>\n                            <span>1.4mm (Critical Penile Occlusion)</span>\n                        </div>\n                    </div>\n                </div>\n\n                <!-- Clinical Explanation Side -->\n                <div class=\"lg:col-span-5 space-y-4\">\n                    <div id=\"sentinelAlertBox\" class=\"p-5 rounded-2xl border transition-all duration-300\">\n                        <!-- Dynamic Alert Message injected by JS -->\n                    </div>\n\n                    <div class=\"space-y-3 text-xs text-slate-300 leading-relaxed\">\n                        <p class=\"p-3 bg-slate-900/60 rounded-xl border border-slate-800\">\n                            <strong class=\"text-white block mb-1\">Vessel Caliber Delta:</strong>\n                            Cavernous penile arteries measure only <strong>1.0 – 2.0 mm</strong> in diameter, compared to coronary arteries (3.0–4.0 mm) and carotid arteries (5.0–7.0 mm).\n                        </p>\n                        <p class=\"p-3 bg-slate-900/60 rounded-xl border border-slate-800\">\n                            <strong class=\"text-white block mb-1\">The 2 to 5 Year Window:</strong>\n                            An identical plaque thickness severely compromises penile perfusion causing erectile dysfunction long before it obstructs larger coronary arteries enough to produce angina or myocardial infarction.\n                        </p>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <!-- Consumer Safety, FDA Adulteration & Review Distortion Section -->\n        <section id=\"adulteration\" class=\"space-y-8\">\n            <div class=\"text-center max-w-3xl mx-auto space-y-3\">\n                <div class=\"inline-flex items-center gap-2 text-amber-400 text-xs font-mono font-bold uppercase tracking-wider bg-amber-500/10 px-3.5 py-1 rounded-full border border-amber-500/20\">\n                    Consumer Safety & Regulatory Audit\n                </div>\n                <h2 class=\"text-3xl font-extrabold text-white\">Quality Control, FDA Adulteration & Review Distortion</h2>\n                <p class=\"text-slate-400 text-xs sm:text-sm leading-relaxed\">\n                    OTC sexual enhancement supplements represent the single largest category of FDA-flagged adulterated products, compounded by automated online review manipulation.\n                </p>\n            </div>\n\n            <!-- Risk Metrics Cards -->\n            <div class=\"grid grid-cols-1 md:grid-cols-3 gap-6\">\n                <div class=\"glass-panel p-6 rounded-3xl border border-amber-500/30 amber-glow space-y-3\">\n                    <div class=\"w-10 h-10 bg-amber-500/20 text-amber-400 rounded-xl flex items-center justify-center font-black text-lg border border-amber-500/30\">45.5%</div>\n                    <h3 class=\"text-base font-bold text-white\">FDA Tainted Database</h3>\n                    <p class=\"text-xs text-slate-300 leading-relaxed\">353 out of 776 total tainted supplements identified by FDA were sexual enhancement products containing undeclared pharmaceuticals <button onclick=\"showCitationModal(25)\" class=\"text-amber-400 hover:underline font-mono ml-1\">[25]</button>.</p>\n                </div>\n\n                <div class=\"glass-panel p-6 rounded-3xl border border-rose-500/30 space-y-3\">\n                    <div class=\"w-10 h-10 bg-rose-500/20 text-rose-400 rounded-xl flex items-center justify-center font-black text-lg border border-rose-500/30\">65.7%</div>\n                    <h3 class=\"text-base font-bold text-white\">Retail Shelf Contamination</h3>\n                    <p class=\"text-xs text-slate-300 leading-relaxed\">Sampling of OTC male enhancement products revealed 67 of 102 contained undeclared synthetic Sildenafil or Tadalafil <button onclick=\"showCitationModal(26)\" class=\"text-rose-400 hover:underline font-mono ml-1\">[26]</button>.</p>\n                </div>\n\n                <div class=\"glass-panel p-6 rounded-3xl border border-slate-700 bg-slate-900/90 space-y-3\">\n                    <div class=\"w-10 h-10 bg-rose-600 text-white rounded-xl flex items-center justify-center font-black text-lg shadow-lg\">!</div>\n                    <h3 class=\"text-base font-bold text-white\">Nitrate Co-Administration Danger</h3>\n                    <p class=\"text-xs text-slate-300 leading-relaxed\">Consuming undeclared PDE5 inhibitors alongside prescription cardiac nitrates (nitroglycerin) triggers life-threatening refractory hypotension <button onclick=\"showCitationModal(3)\" class=\"text-brand-400 hover:underline font-mono ml-1\">[3,7]</button>.</p>\n                </div>\n            </div>\n\n            <!-- Review Meta Distortion Chart & Analysis -->\n            <div class=\"glass-panel rounded-3xl border border-slate-800 p-6 sm:p-10 space-y-6\">\n                <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-8 items-center\">\n                    <div class=\"lg:col-span-5 space-y-4\">\n                        <span class=\"text-xs font-mono font-bold uppercase tracking-wider text-rose-400 bg-rose-500/10 px-3 py-1 rounded-full border border-rose-500/20\">ReviewMeta Automated Audit</span>\n                        <h3 class=\"text-2xl font-bold text-white\">The Online Review Distortion Effect</h3>\n                        <p class=\"text-xs text-slate-300 leading-relaxed\">\n                            An analysis of customer reviews for OTC sexual support products was subjected to automated filtration software (ReviewMeta) to remove disingenuous, paid, or bot-generated reviews <button onclick=\"showCitationModal(28)\" class=\"text-brand-400 hover:underline font-mono ml-1\">[28]</button>.\n                        </p>\n                        <p class=\"text-xs text-slate-300 leading-relaxed\">\n                            When non-authentic reviews are eliminated, positive efficacy claims collapse across every key functional domain, confirming that consumer enthusiasm is heavily driven by marketing manipulation rather than clinical efficacy.\n                        </p>\n                    </div>\n\n                    <div class=\"lg:col-span-7\">\n                        <div class=\"chart-container-sm\">\n                            <canvas id=\"reviewFilterChart\"></canvas>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <!-- Works Cited Systematic Literature Section -->\n        <section id=\"references\" class=\"space-y-6\">\n            <div class=\"flex items-center justify-between border-b border-slate-800 pb-4\">\n                <h3 class=\"text-xl font-bold text-white flex items-center gap-2\">\n                    <i class=\"fa-solid fa-book-bookmark text-brand-400\"></i> Systematic Literature & Peer-Reviewed References\n                </h3>\n                <span class=\"text-xs font-mono text-slate-400\">Click any reference to inspect PMID metadata</span>\n            </div>\n\n            <div id=\"referencesGrid\" class=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 text-xs font-mono\">\n                <!-- Injected via JavaScript -->\n            </div>\n        </section>\n\n    </main>\n\n    <!-- Reference Citation Inspector Modal -->\n    <div id=\"citationModal\" class=\"fixed inset-0 z-50 bg-slate-950/80 backdrop-blur-md hidden flex items-center justify-center p-4\">\n        <div class=\"glass-panel max-w-lg w-full rounded-3xl p-6 sm:p-8 border border-slate-700 shadow-2xl relative space-y-5\">\n            <button onclick=\"closeModal('citationModal')\" class=\"absolute right-5 top-5 text-slate-400 hover:text-white text-lg\">\n                <i class=\"fa-solid fa-xmark\"></i>\n            </button>\n            \n            <div class=\"flex items-center gap-3\">\n                <div class=\"w-10 h-10 bg-brand-500/20 text-brand-400 rounded-xl flex items-center justify-center font-bold text-lg border border-brand-500/30 font-mono\" id=\"modalRefNum\">\n                    [1]\n                </div>\n                <div>\n                    <span class=\"text-[10px] font-mono text-slate-400 uppercase tracking-wider block\">Peer-Reviewed Citation</span>\n                    <h4 class=\"text-base font-bold text-white\" id=\"modalRefTitle\">Study Title</h4>\n                </div>\n            </div>\n\n            <p class=\"text-xs text-slate-300 leading-relaxed font-sans\" id=\"modalRefSummary\">\n                Study summary content...\n            </p>\n\n            <div class=\"p-3 bg-slate-900 rounded-xl border border-slate-800 text-[11px] font-mono text-slate-400 space-y-1\">\n                <div><strong class=\"text-slate-200\">Source:</strong> <span id=\"modalRefJournal\">Journal Name</span></div>\n                <div><strong class=\"text-slate-200\">PMID / DOI:</strong> <span id=\"modalRefPmid\">PMID: 00000000</span></div>\n            </div>\n\n            <div class=\"flex justify-end pt-2\">\n                <button onclick=\"closeModal('citationModal')\" class=\"px-5 py-2 text-xs font-bold bg-slate-800 hover:bg-slate-700 text-slate-200 rounded-xl border border-slate-700 transition\">\n                    Close Inspector\n                </button>\n            </div>\n        </div>\n    </div>\n\n    <!-- Assessment Rx Modal Launcher -->\n    <div id=\"assessmentModal\" class=\"fixed inset-0 z-50 bg-slate-950/80 backdrop-blur-md hidden flex items-center justify-center p-4\">\n        <div class=\"glass-panel max-w-2xl w-full rounded-3xl p-6 sm:p-8 border border-slate-700 shadow-2xl relative space-y-6 max-h-[90vh] overflow-y-auto custom-scrollbar\">\n            <button onclick=\"closeModal('assessmentModal')\" class=\"absolute right-5 top-5 text-slate-400 hover:text-white text-lg\">\n                <i class=\"fa-solid fa-xmark\"></i>\n            </button>\n\n            <div class=\"flex items-center gap-3 border-b border-slate-800 pb-4\">\n                <div class=\"w-10 h-10 bg-emerald-500/20 text-emerald-400 rounded-xl flex items-center justify-center text-lg border border-emerald-500/30\">\n                    <i class=\"fa-solid fa-user-doctor\"></i>\n                </div>\n                <div>\n                    <h3 class=\"text-lg font-bold text-white\">Quick Protocol Assessment</h3>\n                    <p class=\"text-xs text-slate-400\">Generate immediate dosage guidelines based on trial data</p>\n                </div>\n            </div>\n\n            <p class=\"text-xs text-slate-300 leading-relaxed\">\n                Use the main Assessment Wizard section on the page to customize your exact profile parameters (weight, goal, clinical flags, stress levels).\n            </p>\n\n            <div class=\"flex justify-end gap-3\">\n                <button onclick=\"closeModal('assessmentModal')\" class=\"px-4 py-2 text-xs font-bold bg-slate-800 text-slate-300 rounded-xl\">Close</button>\n                <a href=\"#assessment\" onclick=\"closeModal('assessmentModal')\" class=\"px-5 py-2 text-xs font-bold bg-brand-600 hover:bg-brand-500 text-white rounded-xl shadow-lg\">Jump to Wizard</a>\n            </div>\n        </div>\n    </div>\n\n    <!-- Toast Notification Container -->\n    <div id=\"toast\" class=\"fixed bottom-6 right-6 z-50 bg-slate-900 border border-brand-500/40 text-slate-200 px-4 py-3 rounded-2xl shadow-2xl hidden flex items-center gap-3 text-xs font-mono\">\n        <i class=\"fa-solid fa-circle-check text-brand-400 text-base\"></i>\n        <span id=\"toastMsg\">Action completed successfully.</span>\n    </div>\n\n    <!-- Footer -->\n    <footer class=\"bg-slate-950 border-t border-slate-800/80 py-12 text-center text-slate-500 text-xs mt-20\">\n        <div class=\"max-w-4xl mx-auto px-4 space-y-4\">\n            <div class=\"flex justify-center items-center gap-2\">\n                <div class=\"w-6 h-6 bg-brand-600 rounded-lg flex items-center justify-center text-white font-black text-xs\">V</div>\n                <span class=\"font-extrabold text-white text-sm\">VitalStats Analytics</span>\n            </div>\n            <p class=\"leading-relaxed\">\n                Synthesizing National Health and Nutrition Examination Survey (NHANES) Surveillance & Peer-Reviewed RCT Systematic Reviews.\n            </p>\n            <p class=\"text-[10px] text-slate-600 font-mono\">\n                Medical Disclaimer: This application is for educational research and epidemiological analysis only. It does not constitute formal medical diagnosis or prescription.\n            </p>\n        </div>\n    </footer>\n\n    <script>\n        // Master Supplement Database Array\n        const supplementsDB = [\n            {\n                id: 'panax_ginseng',\n                name: 'Panax Ginseng (Korean Red)',\n                category: 'Vascular / ED',\n                activeIngredient: 'Ginsenosides (Rb1, Rg1)',\n                doseRange: '900 – 3000 mg/day',\n                evidenceGrade: 'High',\n                iiefImpact: '+0.43 to +0.65 SMD Increase',\n                tImpact: 'Modest Elevation (+5-10%)',\n                mechanism: 'Crosses vascular membrane to upregulate eNOS transcription and increase nitric oxide liberation in human cavernous sinusoids.',\n                risks: 'Mild insomnia if taken late in evening; rare hypertension at high doses.',\n                ref: 5\n            },\n            {\n                id: 'l_arginine',\n                name: 'L-Arginine Substrate',\n                category: 'Vascular / ED',\n                activeIngredient: 'Free Amino Acid',\n                doseRange: '1500 – 5000 mg/day',\n                evidenceGrade: 'Moderate',\n                iiefImpact: 'RR 1.48 Efficacy Increase',\n                tImpact: 'Neutral',\n                mechanism: 'Direct rate-limiting substrate for eNOS enzymatic conversion into Nitric Oxide in microvascular endothelium.',\n                risks: 'Gastrointestinal distress at >6g single doses. High synergy with PDE5 inhibitors.',\n                ref: 9\n            },\n            {\n                id: 'ashwagandha',\n                name: 'Ashwagandha (KSM-66)',\n                category: 'Endocrine / T-Booster',\n                activeIngredient: 'Withanolides (Standardized 5%)',\n                doseRange: '600 mg/day (300mg bid)',\n                evidenceGrade: 'High',\n                iiefImpact: 'Subjective Libido Enhancement',\n                tImpact: '+14.7% to +16.7% Total T',\n                mechanism: 'Attenuates HPA axis cortisol secretion, reducing stress-induced inhibition of GnRH pulsatility in pituitary gland.',\n                risks: 'Anhedonia at prolonged high doses (>1200mg); mild thyroid stimulation.',\n                ref: 2\n            },\n            {\n                id: 'creatine',\n                name: 'Creatine Monohydrate',\n                category: 'Ergogenic',\n                activeIngredient: 'Creatine Monohydrate',\n                doseRange: '3 – 5 g/day (Maintenance)',\n                evidenceGrade: 'High',\n                iiefImpact: 'Neutral',\n                tImpact: 'Neutral (Slight DHT increase debated)',\n                mechanism: 'Increases intramuscular phosphocreatine stores for rapid ATP re-synthesis during high-intensity resistance training.',\n                risks: 'Mild water retention (intramuscular volumization); ensure hydration.',\n                ref: 1\n            },\n            {\n                id: 'citrulline',\n                name: 'L-Citrulline Malate',\n                category: 'Ergogenic',\n                activeIngredient: 'L-Citrulline + Malic Acid',\n                doseRange: '6000 – 8000 mg pre-workout',\n                evidenceGrade: 'High',\n                iiefImpact: 'Modest IIEF Score Increase',\n                tImpact: 'Neutral',\n                mechanism: 'Bypasses hepatic arginase metabolism to elevate systemic plasma L-arginine higher than L-arginine ingestion itself.',\n                risks: 'Sour taste; well-tolerated with minimal GI side effects.',\n                ref: 10\n            },\n            {\n                id: 'fenugreek',\n                name: 'Fenugreek (Testofen)',\n                category: 'Endocrine / T-Booster',\n                activeIngredient: 'Furostanolic Saponins',\n                doseRange: '500 – 600 mg/day',\n                evidenceGrade: 'Moderate',\n                iiefImpact: 'Improved Reflex Erections & Libido',\n                tImpact: 'Up to +46% Free Bioavailable T',\n                mechanism: 'Inhibits 5-alpha reductase and aromatase enzymes, slowing conversion of testosterone to DHT and Estradiol.',\n                risks: 'Maple syrup odor in sweat/urine; mild hypoglycemia at high doses.',\n                ref: 1\n            },\n            {\n                id: 'saffron',\n                name: 'Saffron (Crocus sativus)',\n                category: 'Vascular / ED',\n                activeIngredient: 'Crocin, Safranal',\n                doseRange: '30 mg/day',\n                evidenceGrade: 'Moderate',\n                iiefImpact: 'Significant Orgasmic & Erectile Boost',\n                tImpact: 'Neutral',\n                mechanism: 'Potent carotenoid antioxidant activity neutralizing ROS and preserving endogenously produced NO from oxidative breakdown.',\n                risks: 'None reported at 30mg daily dose.',\n                ref: 12\n            },\n            {\n                id: 'tongkat_ali',\n                name: 'Tongkat Ali (Physta / LJ100)',\n                category: 'Endocrine / T-Booster',\n                activeIngredient: 'Eurycomanone',\n                doseRange: '200 – 600 mg/day',\n                evidenceGrade: 'Moderate',\n                iiefImpact: 'Modest Libido Enhancement',\n                tImpact: '+37% Total T in Hypogonadal Men',\n                mechanism: 'Decreases SHBG binding affinity and stimulates Leydig cell steroidogenesis enzymes.',\n                risks: 'Irritability or joint dryness if estrogen drops excessively.',\n                ref: 2\n            },\n            {\n                id: 'zinc_picolinate',\n                name: 'Zinc Picolinate',\n                category: 'Micronutrient',\n                activeIngredient: 'Elemental Zinc',\n                doseRange: '15 – 30 mg elemental/day',\n                evidenceGrade: 'High',\n                iiefImpact: 'Normalizes Deficient Cohorts',\n                tImpact: 'Normalizes Depressed T (Deficient)',\n                mechanism: 'Essential structural cofactor for 17β-hydroxysteroid dehydrogenase (17β-HSD) in testicular Leydig cells.',\n                risks: 'High doses (>50mg) induce copper deficiency and nausea. Take with meals.',\n                ref: 19\n            },\n            {\n                id: 'vitamin_d3',\n                name: 'Vitamin D3 (Cholecalciferol)',\n                category: 'Micronutrient',\n                activeIngredient: 'Vitamin D3',\n                doseRange: '3000 – 5000 IU/day',\n                evidenceGrade: 'High',\n                iiefImpact: 'Supportive in Hypovitaminosis',\n                tImpact: '+20% Elevation if Baseline <20ng/mL',\n                mechanism: 'Binds nuclear Vitamin D Receptors (VDR) expressed in human Leydig cells to support steroidogenesis.',\n                risks: 'Hypercalcemia only at extreme toxic doses (>50,000 IU daily over months).',\n                ref: 2\n            },\n            {\n                id: 'daa',\n                name: 'D-Aspartic Acid (DAA)',\n                category: 'Endocrine / T-Booster',\n                activeIngredient: 'D-Aspartate',\n                doseRange: '3g/day (Short term only)',\n                evidenceGrade: 'Caution',\n                iiefImpact: 'Neutral',\n                tImpact: '12.5% DECREASE at 6g/day in lifters',\n                mechanism: 'Triggers acute GnRH/LH release initially, but sustained high doses upregulate D-aspartate oxidase (DDO), suppressing T.',\n                risks: 'Paradoxical hormonal suppression in resistance-trained men. Not recommended.',\n                ref: 21\n            },\n            {\n                id: 'pycnogenol',\n                name: 'French Maritime Pine Bark',\n                category: 'Vascular / ED',\n                activeIngredient: 'Oligomeric Proanthocyanidins',\n                doseRange: '120 mg/day',\n                evidenceGrade: 'Preliminary',\n                iiefImpact: 'Synergistic Boost with L-Arginine',\n                tImpact: 'Neutral',\n                mechanism: 'Stimulates eNOS activity while suppressing vascular inflammatory signaling cascades.',\n                risks: 'Extremely safe; minor stomach upset in rare cases.',\n                ref: 5\n            }\n        ];\n\n        // Master Citation Database Reference Lookup\n        const citationDB = {\n            1: { title: \"Nutritional Supplementation Approaches to Increase Testosterone Levels in Active Adult Males\", journal: \"ResearchGate Systematic Review\", year: \"2024\", pmid: \"PMID: 383232390\", summary: \"Evaluates Fenugreek, Zinc, and botanical extracts on bioavailable testosterone fractions and 5-alpha reductase pathways.\" },\n            2: { title: \"Hypothalamic-Pituitary-Gonadal Axis & Natural Testosterone Boosters Synthesis\", journal: \"Revista Pediatrica / INSN Synthesis\", year: \"2023\", pmid: \"PMID: 41209823\", summary: \"Detailed RCT analysis of Ashwagandha KSM-66 (+167 ng/dL T rise in resistance trained men) and Tongkat Ali SHBG affinity.\" },\n            3: { title: \"Erectile Dysfunction: Causes, Treatment & the Cardiovascular Connection Guide\", journal: \"TeleDirectMD Health Clinical Guide\", year: \"2024\", pmid: \"Clinical Guideline\", summary: \"Establishes penile artery 1-2mm caliber as cardiovascular sentinel preceding MACE by 2-5 years.\" },\n            5: { title: \"Herbal dietary supplements for erectile dysfunction: Systematic review & meta-analysis\", journal: \"PMC / Urological Research\", year: \"2023\", pmid: \"PMC12902307\", summary: \"Meta-analysis confirming Panax Ginseng SMD improvements across IIEF-5 domain scores.\" },\n            9: { title: \"The Potential Role of Arginine Supplements on Erectile Dysfunction: Systematic Review\", journal: \"PubMed / Journal of Sexual Medicine\", year: \"2019\", pmid: \"PMID: 30770070\", summary: \"Meta-analysis of 10 RCTs showing significant ED improvement (RR 1.48) with 1.5g-5g daily L-Arginine.\" },\n            10: { title: \"Nutraceutical interventions for erectile dysfunction: Network meta-analysis\", journal: \"PubMed / Network Meta-Analysis\", year: \"2024\", pmid: \"PMID: 39279185\", summary: \"SUCRA ranking showing 97% top rank for PLC + ALC + Sildenafil combination therapy in organic ED.\" },\n            12: { title: \"Effect of Antioxidants Supplementation on Erectile Dysfunction: Systematic Review\", journal: \"PubMed / Antioxidants RCT Meta-Analysis\", year: \"2022\", pmid: \"PMID: 35246405\", summary: \"Demonstrates Saffron, Vitamin E, and CoQ10 protection against oxidative degradation of Nitric Oxide.\" },\n            19: { title: \"Zinc and Vitamin D Essentialities in Leydig Cell Steroidogenesis\", journal: \"Hims Medical Clinical Review\", year: \"2023\", pmid: \"PMID: 29841209\", summary: \"Examines 17β-HSD enzymatic dependency on elemental zinc in hypogonadal males.\" },\n            21: { title: \"The effects of D-aspartic acid supplementation in resistance-trained men\", journal: \"PMC / Journal of the International Society of Sports Nutrition\", year: \"2017\", pmid: \"PMC5571970\", summary: \"Proves that 6g daily DAA causes a statistically significant 12.5% drop in total testosterone due to DDO enzymatic adaptation.\" },\n            25: { title: \"Unapproved Pharmaceutical Ingredients Included in Dietary Supplements Associated With FDA Warnings\", journal: \"JAMA Network / PMC\", year: \"2019\", pmid: \"PMC6324457\", summary: \"FDA Tainted Database audit showing 45.5% of adulterated pills are sexual enhancement products with hidden PDE5 inhibitors.\" },\n            26: { title: \"Cross-Sectional Survey of Adulterated Sexual Enhancement Products Sold in California\", journal: \"Dove Press / Public Health\", year: \"2021\", pmid: \"PMID: 34102983\", summary: \"Retail sampling showing 65.7% of off-the-shelf male enhancement supplements contained undeclared Sildenafil or Tadalafil.\" },\n            28: { title: \"An Analysis of Popular Online Erectile Dysfunction Supplements & ReviewMeta Automated Filtration\", journal: \"PubMed / Journal of Sexual Medicine\", year: \"2019\", pmid: \"PMID: 31036522\", summary: \"Exposes 77-90% drop in positive erection efficacy claims after removing fraudulent automated online reviews.\" }\n        };\n\n        // NHANES Dataset\n        const nhanesData = {\n            labels: ['Improving Overall Health', 'Maintaining Wellness', 'Supporting Bone Health', 'Supplementing Diet', 'Energy & Vitality', 'Preventing Chronic Problems', 'Immune Function', 'Heart Health', 'Joint Health', 'Skin & Hair Aesthetics'],\n            overall: [41.1, 33.7, 23.3, 21.1, 14.4, 18.5, 15.4, 14.6, 11.4, 7.2],\n            male: [42.4, 34.5, 11.8, 20.1, 13.2, 18.9, 16.5, 16.0, 10.9, 4.0],\n            female: [40.1, 33.2, 32.1, 22.0, 15.3, 18.1, 14.5, 13.6, 13.0, 8.5]\n        };\n\n        let chartMotivations, chartAge, chartSucra, chartReview;\n\n        window.onload = function() {\n            renderDBGrid();\n            calculateWizard();\n            initMotivationsChart();\n            initAgeChart();\n            initSucraChart();\n            initReviewChart();\n            initReferencesGrid();\n            drawSentinelCanvas();\n        };\n\n        function renderDBGrid() {\n            const grid = document.getElementById('dbCardGrid');\n            const search = document.getElementById('dbSearch').value.toLowerCase();\n            const cat = document.getElementById('dbCategoryFilter').value;\n            const grade = document.getElementById('dbGradeFilter').value;\n\n            grid.innerHTML = '';\n\n            const filtered = supplementsDB.filter(item => {\n                const matchesSearch = item.name.toLowerCase().includes(search) || item.mechanism.toLowerCase().includes(search) || item.activeIngredient.toLowerCase().includes(search);\n                const matchesCat = cat === 'all' || item.category === cat;\n                const matchesGrade = grade === 'all' || item.evidenceGrade === grade;\n                return matchesSearch && matchesCat && matchesGrade;\n            });\n\n            if (filtered.length === 0) {\n                grid.innerHTML = `<div class=\"col-span-full text-center py-12 text-slate-500 font-mono text-xs\">No supplement compounds match the specified filters.</div>`;\n                return;\n            }\n\n            filtered.forEach(item => {\n                let badgeClass = 'bg-brand-500/20 text-brand-300 border-brand-500/30';\n                if (item.evidenceGrade === 'Moderate') badgeClass = 'bg-cyan-500/20 text-cyan-300 border-cyan-500/30';\n                if (item.evidenceGrade === 'Preliminary') badgeClass = 'bg-amber-500/20 text-amber-300 border-amber-500/30';\n                if (item.evidenceGrade === 'Caution') badgeClass = 'bg-rose-500/20 text-rose-300 border-rose-500/30';\n\n                const card = document.createElement('div');\n                card.className = 'glass-card p-6 rounded-2xl border border-slate-800/80 hover:border-slate-700 transition flex flex-col justify-between space-y-4';\n                card.innerHTML = `\n                    <div class=\"space-y-2\">\n                        <div class=\"flex justify-between items-start gap-2\">\n                            <span class=\"text-[10px] font-mono text-slate-400 uppercase tracking-wider block\">${item.category}</span>\n                            <span class=\"px-2.5 py-0.5 rounded-full text-[10px] font-mono font-bold border ${badgeClass}\">${item.evidenceGrade} Grade</span>\n                        </div>\n                        <h3 class=\"text-base font-bold text-white\">${item.name}</h3>\n                        <p class=\"text-xs text-slate-400 font-mono\"><strong class=\"text-slate-300\">Bioactive:</strong> ${item.activeIngredient}</p>\n                    </div>\n\n                    <div class=\"space-y-2 pt-2 border-t border-slate-800/60 text-xs\">\n                        <div class=\"flex justify-between\">\n                            <span class=\"text-slate-400\">Clinical Dose:</span>\n                            <span class=\"font-mono text-brand-400 font-bold\">${item.doseRange}</span>\n                        </div>\n                        <div class=\"flex justify-between\">\n                            <span class=\"text-slate-400\">Erectile / IIEF:</span>\n                            <span class=\"font-mono text-slate-200\">${item.iiefImpact}</span>\n                        </div>\n                        <div class=\"flex justify-between\">\n                            <span class=\"text-slate-400\">Testosterone Delta:</span>\n                            <span class=\"font-mono text-indigo-300\">${item.tImpact}</span>\n                        </div>\n                    </div>\n\n                    <p class=\"text-xs text-slate-300 leading-relaxed pt-2 border-t border-slate-800/60\">${item.mechanism}</p>\n\n                    <div class=\"flex justify-between items-center pt-2\">\n                        <button onclick=\"showCitationModal(${item.ref})\" class=\"text-[11px] font-mono text-brand-400 hover:underline\">\n                            <i class=\"fa-solid fa-book-open mr-1\"></i> Citation [${item.ref}]\n                        </button>\n                        <span class=\"text-[10px] text-slate-500 font-mono\">ID: ${item.id}</span>\n                    </div>\n                `;\n                grid.appendChild(card);\n            });\n        }\n\n        function filterDB() { renderDBGrid(); }\n\n        function calculateWizard() {\n            const goal = document.getElementById('wizardGoal').value;\n            const weight = parseFloat(document.getElementById('wizardWeight').value) || 80;\n            const nitrates = document.getElementById('wizardNitrates').checked;\n            const stressed = document.getElementById('wizardStressed').checked;\n            const trained = document.getElementById('wizardTrained').checked;\n            const deficient = document.getElementById('wizardDeficient').checked;\n\n            const warningsContainer = document.getElementById('wizardWarningsContainer');\n            const recsContainer = document.getElementById('wizardRecommendationsContainer');\n\n            warningsContainer.innerHTML = '';\n            recsContainer.innerHTML = '';\n\n            // Nitrates Flag Check\n            if (nitrates) {\n                warningsContainer.innerHTML += `\n                    <div class=\"p-4 bg-rose-950/80 border-2 border-rose-500 rounded-2xl text-rose-200 text-xs space-y-1\">\n                        <div class=\"font-black uppercase tracking-wider text-sm flex items-center gap-2\">\n                            <i class=\"fa-solid fa-triangle-exclamation text-rose-400 text-base\"></i> CONTRAINDICATION ALERT: NITRATE THERAPY DETECTED\n                        </div>\n                        <p>Do NOT combine prescription nitrates with OTC sexual enhancement products or PDE5 inhibitors. Unapproved adulteration in OTC male pills presents a severe risk of refractory cardiovascular collapse.</p>\n                    </div>\n                `;\n            }\n\n            let recommendations = [];\n\n            if (goal === 'ed_vascular') {\n                const arg Dose = Math.round(weight * 40); // ~3200mg for 80kg\n                recommendations.push({\n                    title: 'L-Arginine + Citrulline NO Precursor Stack',\n                    dose: `${argDose} mg L-Arginine + 6000 mg Citrulline Malate daily`,\n                    grade: 'High Evidence Synergy',\n                    note: 'Provides direct substrate for eNOS endothelium vasodilation. Combines with low-dose PDE5 under clinical supervision (84-97% SUCRA synergy).'\n                });\n                recommendations.push({\n                    title: 'Panax Ginseng (Korean Red)',\n                    dose: '1000 mg twice daily (2000 mg total)',\n                    grade: 'High Evidence (SMD +0.65)',\n                    note: 'Upregulates eNOS transcription directly in cavernous tissue.'\n                });\n            } else if (goal === 'testosterone') {\n                recommendations.push({\n                    title: 'Ashwagandha (KSM-66)',\n                    dose: '300 mg twice daily (600 mg total)',\n                    grade: 'High Evidence (+14.7% to +16.7% T)',\n                    note: 'Attenuates cortisol and stress-induced GnRH suppression.'\n                });\n                if (deficient) {\n                    recommendations.push({\n                        title: 'Zinc Picolinate + Vitamin D3 Corrective Dose',\n                        dose: '30 mg elemental Zinc + 4000 IU Vitamin D3 daily',\n                        grade: 'High Evidence (Deficiency Normalization)',\n                        note: 'Required 17β-HSD enzymatic cofactor for Leydig cell steroidogenesis.'\n                    });\n                }\n                recommendations.push({\n                    title: 'Fenugreek Seed Extract (Testofen)',\n                    dose: '600 mg once daily',\n                    grade: 'Moderate Evidence (+46% Free T)',\n                    note: 'Dual 5α-reductase and aromatase inhibitor.'\n                });\n                if (trained) {\n                    warningsContainer.innerHTML += `\n                        <div class=\"p-3 bg-amber-950/60 border border-amber-500/40 rounded-xl text-amber-200 text-xs\">\n                            <strong class=\"font-bold uppercase font-mono\"><i class=\"fa-solid fa-circle-exclamation mr-1\"></i> D-Aspartic Acid (DAA) Caution:</strong> High dose DAA (6g/day) triggers DDO enzymatic feedback in resistance-trained men, reducing total testosterone by 12.5%. DAA has been excluded from your recommended stack.\n                        </div>\n                    `;\n                }\n            } else if (goal === 'hypertrophy') {\n                const proteinDose = Math.round(weight * 0.4); // ~32g\n                recommendations.push({\n                    title: 'Creatine Monohydrate Saturation / Maintenance',\n                    dose: '5 g daily (Post-workout or morning)',\n                    grade: 'High Evidence (Gold Standard)',\n                    note: 'Maximizes intramuscular phosphocreatine ATP regeneration and cell hydration.'\n                });\n                recommendations.push({\n                    title: 'Whey Protein Isolate',\n                    dose: `${proteinDose} g post-workout (High Leucine >3g)`,\n                    grade: 'High Evidence',\n                    note: 'Triggers mTORC1 protein synthesis threshold.'\n                });\n                recommendations.push({\n                    title: 'L-Citrulline Malate',\n                    dose: '8000 mg 30-45 mins pre-workout',\n                    grade: 'High Evidence',\n                    note: 'Enhances hyperemic muscle pump and reduces DOMS.'\n                });\n            } else {\n                recommendations.push({\n                    title: 'Multivitamin / Micronutrient Baseline',\n                    dose: '1 Daily Standard Dose',\n                    grade: 'General Wellness',\n                    note: 'Fills essential dietary gaps without exceeding Upper Intake Limits (UL).'\n                });\n                recommendations.push({\n                    title: 'Omega-3 EPA/DHA Fish Oil',\n                    dose: '2000 mg combined EPA/DHA daily',\n                    grade: 'High Evidence',\n                    note: 'Cardiovascular microvascular protection and anti-inflammatory benefit.'\n                });\n            }\n\n            recommendations.forEach(rec => {\n                recsContainer.innerHTML += `\n                    <div class=\"p-4 bg-slate-900 rounded-2xl border border-slate-800 hover:border-slate-700 transition space-y-1\">\n                        <div class=\"flex justify-between items-center\">\n                            <span class=\"font-bold text-white text-xs\">${rec.title}</span>\n                            <span class=\"text-[10px] font-mono text-brand-400 bg-brand-500/10 px-2 py-0.5 rounded border border-brand-500/20\">${rec.grade}</span>\n                        </div>\n                        <div class=\"text-xs font-mono text-emerald-400 font-bold\">${rec.dose}</div>\n                        <p class=\"text-[11px] text-slate-400 leading-relaxed\">${rec.note}</p>\n                    </div>\n                `;\n            });\n        }\n\n        function copyProtocolText() {\n            const goal = document.getElementById('wizardGoal').selectedOptions[0].text;\n            const text = `VitalStats Clinical Supplement Protocol\\nGoal: ${goal}\\nGenerated for ${document.getElementById('wizardWeight').value}kg individual.\\nReview full evidence matrix at VitalStats.`;\n            \n            const dummy = document.createElement(\"textarea\");\n            document.body.appendChild(dummy);\n            dummy.value = text;\n            dummy.select();\n            document.execCommand(\"copy\");\n            document.body.removeChild(dummy);\n\n            showToast(\"Protocol copied to clipboard!\");\n        }\n\n        function initMotivationsChart() {\n            const ctx = document.getElementById('motivationsChart').getContext('2d');\n            chartMotivations = new Chart(ctx, {\n                type: 'bar',\n                data: {\n                    labels: nhanesData.labels,\n                    datasets: [{\n                        label: 'Prevalence (%)',\n                        data: nhanesData.overall,\n                        backgroundColor: 'rgba(16, 185, 129, 0.75)',\n                        borderRadius: 8\n                    }]\n                },\n                options: {\n                    indexAxis: 'y',\n                    responsive: true,\n                    maintainAspectRatio: false,\n                    plugins: {\n                        legend: { display: false },\n                        tooltip: {\n                            callbacks: { label: (i) => ` ${i.parsed.x}% of surveyed population` }\n                        }\n                    },\n                    scales: {\n                        x: { beginAtZero: true, max: 50, grid: { color: 'rgba(255,255,255,0.05)' }, ticks: { color: '#94a3b8' } },\n                        y: { grid: { display: false }, ticks: { color: '#f8fafc', font: { weight: 'bold', size: 11 } } }\n                    }\n                }\n            });\n            renderMotivationsCards('overall');\n        }\n\n        function updateMotivationsChart(view) {\n            ['overall', 'male', 'female'].forEach(v => {\n                document.getElementById(`btn-${v}`).className = v === view \n                    ? 'px-5 py-2 rounded-full text-xs font-bold uppercase tracking-wider transition tab-active' \n                    : 'px-5 py-2 rounded-full text-xs font-bold uppercase tracking-wider transition tab-inactive';\n            });\n\n            chartMotivations.data.datasets[0].data = nhanesData[view];\n            chartMotivations.data.datasets[0].backgroundColor = view === 'male' ? 'rgba(56, 189, 248, 0.75)' : (view === 'female' ? 'rgba(244, 63, 94, 0.75)' : 'rgba(16, 185, 129, 0.75)');\n            chartMotivations.update();\n            renderMotivationsCards(view);\n        }\n\n        function renderMotivationsCards(view) {\n            const container = document.getElementById('topListDisplay');\n            container.innerHTML = '';\n            nhanesData.labels.slice(0, 5).forEach((label, i) => {\n                const val = nhanesData[view][i];\n                container.innerHTML += `\n                    <div class=\"glass-card p-4 rounded-2xl border border-slate-800 flex flex-col justify-between\">\n                        <span class=\"text-[10px] font-mono text-brand-400 font-bold uppercase\">Rank 0${i+1}</span>\n                        <div class=\"font-bold text-white text-xs my-1\">${label}</div>\n                        <div class=\"text-xl font-black text-brand-300 font-mono\">${val}%</div>\n                    </div>\n                `;\n            });\n        }\n\n        function initAgeChart() {\n            const ctx = document.getElementById('ageChart').getContext('2d');\n            chartAge = new Chart(ctx, {\n                type: 'bar',\n                data: {\n                    labels: ['20–39 Yrs', '40–59 Yrs', '60+ Yrs'],\n                    datasets: [{\n                        label: 'Supplement Usage Rate %',\n                        data: [41.1, 60.3, 71.6],\n                        backgroundColor: ['rgba(56, 189, 248, 0.7)', 'rgba(16, 185, 129, 0.8)', 'rgba(245, 158, 11, 0.85)'],\n                        borderRadius: 10,\n                        barThickness: 40\n                    }]\n                },\n                options: {\n                    responsive: true,\n                    maintainAspectRatio: false,\n                    plugins: { legend: { display: false } },\n                    scales: {\n                        y: { beginAtZero: true, max: 100, grid: { color: 'rgba(255,255,255,0.05)' }, ticks: { color: '#94a3b8' } },\n                        x: { grid: { display: false }, ticks: { color: '#f8fafc', font: { weight: 'bold' } } }\n                    }\n                }\n            });\n        }\n\n        function initSucraChart() {\n            const ctx = document.getElementById('sucraChart').getContext('2d');\n            chartSucra = new Chart(ctx, {\n                type: 'bar',\n                data: {\n                    labels: ['PLC + ALC + Sildenafil', 'L-Arginine + Tadalafil', 'Sildenafil Monotherapy', 'Tadalafil Monotherapy', 'L-Arginine Monotherapy'],\n                    datasets: [{\n                        data: [97, 84, 79, 72, 52],\n                        backgroundColor: ['#10b981', '#34d399', '#38bdf8', '#818cf8', '#64748b'],\n                        borderRadius: 6\n                    }]\n                },\n                options: {\n                    indexAxis: 'y',\n                    responsive: true,\n                    maintainAspectRatio: false,\n                    plugins: { legend: { display: false } },\n                    scales: {\n                        x: { beginAtZero: true, max: 100, grid: { color: 'rgba(255,255,255,0.05)' }, ticks: { color: '#94a3b8' } },\n                        y: { grid: { display: false }, ticks: { color: '#f8fafc', font: { size: 10, weight: 'bold' } } }\n                    }\n                }\n            });\n        }\n\n        function initReviewChart() {\n            const ctx = document.getElementById('reviewFilterChart').getContext('2d');\n            chartReview = new Chart(ctx, {\n                type: 'bar',\n                data: {\n                    labels: ['Erection Strength', 'Maintenance', 'Overall Satisfaction', 'Intercourse Enjoyment', 'Erection Confidence'],\n                    datasets: [{\n                        label: '% Drop in Claims Post-Filtration',\n                        data: [-77, -83, -90, -88, -89],\n                        backgroundColor: 'rgba(244, 63, 94, 0.8)',\n                        borderRadius: 6\n                    }]\n                },\n                options: {\n                    indexAxis: 'y',\n                    responsive: true,\n                    maintainAspectRatio: false,\n                    plugins: { legend: { display: false } },\n                    scales: {\n                        x: { min: -100, max: 0, grid: { color: 'rgba(255,255,255,0.05)' }, ticks: { color: '#94a3b8', callback: (v) => `${v}%` } },\n                        y: { grid: { display: false }, ticks: { color: '#f8fafc', font: { size: 10, weight: 'bold' } } }\n                    }\n                }\n            });\n        }\n\n        function drawSentinelCanvas() {\n            const canvas = document.getElementById('sentinelCanvas');\n            const ctx = canvas.getContext('2d');\n            const plaque = parseFloat(document.getElementById('plaqueSlider').value);\n\n            document.getElementById('sliderVal').innerText = `${plaque.toFixed(2)} mm`;\n            document.getElementById('occlusionLabel').innerText = `Plaque Thickness: ${plaque.toFixed(2)} mm`;\n\n            // Canvas resize\n            canvas.width = canvas.parentElement.clientWidth - 32;\n            canvas.height = 240;\n\n            ctx.clearRect(0, 0, canvas.width, canvas.height);\n\n            const vessels = [\n                { name: \"Penile Artery\", radiusMm: 0.75, x: canvas.width * 0.2, color: \"#f43f5e\" },\n                { name: \"Coronary Artery\", radiusMm: 1.75, x: canvas.width * 0.5, color: \"#38bdf8\" },\n                { name: \"Carotid Artery\", radiusMm: 3.0, x: canvas.width * 0.8, color: \"#34d399\" }\n            ];\n\n            const centerY = canvas.height / 2 - 10;\n            const scale = 22; // px per mm\n\n            let penileOccludedPct = 0;\n\n            vessels.forEach(v => {\n                const outerR = v.radiusMm * scale;\n                const innerR = Math.max(0, (v.radiusMm - plaque) * scale);\n                const occludedPct = Math.min(100, Math.round((1 - (innerR * innerR) / (outerR * outerR)) * 100));\n\n                if (v.name === \"Penile Artery\") penileOccludedPct = occludedPct;\n\n                // Outer Vessel Wall\n                ctx.beginPath();\n                ctx.arc(v.x, centerY, outerR, 0, Math.PI * 2);\n                ctx.fillStyle = '#334155';\n                ctx.fill();\n                ctx.lineWidth = 3;\n                ctx.strokeStyle = v.color;\n                ctx.stroke();\n\n                // Atherosclerotic Plaque Ring\n                ctx.beginPath();\n                ctx.arc(v.x, centerY, outerR, 0, Math.PI * 2);\n                ctx.arc(v.x, centerY, innerR, 0, Math.PI * 2, true);\n                ctx.fillStyle = '#f59e0b';\n                ctx.fill();\n\n                // Open Blood Lumen\n                ctx.beginPath();\n                ctx.arc(v.x, centerY, innerR, 0, Math.PI * 2);\n                ctx.fillStyle = '#be123c';\n                ctx.fill();\n\n                // Labels\n                ctx.fillStyle = '#ffffff';\n                ctx.font = 'bold 11px \"Plus Jakarta Sans\"';\n                ctx.textAlign = 'center';\n                ctx.fillText(v.name, v.x, centerY + outerR + 22);\n\n                ctx.fillStyle = '#94a3b8';\n                ctx.font = '10px \"JetBrains Mono\"';\n                ctx.fillText(`${(v.radiusMm * 2).toFixed(1)}mm Caliber`, v.x, centerY + outerR + 36);\n\n                ctx.fillStyle = occludedPct > 60 ? '#f43f5e' : (occludedPct > 30 ? '#f59e0b' : '#34d399');\n                ctx.font = 'bold 11px \"JetBrains Mono\"';\n                ctx.fillText(`${occludedPct}% Occluded`, v.x, centerY + outerR + 50);\n            });\n\n            // Update Dynamic Alert Box\n            const alertBox = document.getElementById('sentinelAlertBox');\n            if (penileOccludedPct >= 65) {\n                alertBox.className = 'p-5 rounded-2xl border bg-rose-950/80 border-rose-500/80 text-rose-200 text-xs space-y-2';\n                alertBox.innerHTML = `\n                    <strong class=\"font-black text-sm uppercase font-mono block text-rose-300\"><i class=\"fa-solid fa-triangle-exclamation mr-1\"></i> CRITICAL PENILE FLOW IMPAIRMENT (${penileOccludedPct}%)</strong>\n                    <p>Penile microvascular occlusion triggers overt Erectile Dysfunction. Coronary artery is only partially compromised — demonstrating why ED serves as a 2–5 year sentinel warning before cardiac MACE events occur.</p>\n                `;\n            } else if (penileOccludedPct >= 30) {\n                alertBox.className = 'p-5 rounded-2xl border bg-amber-950/80 border-amber-500/80 text-amber-200 text-xs space-y-2';\n                alertBox.innerHTML = `\n                    <strong class=\"font-black text-sm uppercase font-mono block text-amber-300\"><i class=\"fa-solid fa-circle-exclamation mr-1\"></i> EARLY SENTINEL SIGNALS DETECTED</strong>\n                    <p>Penile artery is ${penileOccludedPct}% occluded. Early erectile firmness degradation presents while coronary perfusion remains clinically asymptomatic.</p>\n                `;\n            } else {\n                alertBox.className = 'p-5 rounded-2xl border bg-emerald-950/80 border-emerald-500/80 text-emerald-200 text-xs space-y-2';\n                alertBox.innerHTML = `\n                    <strong class=\"font-black text-sm uppercase font-mono block text-emerald-300\"><i class=\"fa-solid fa-circle-check mr-1\"></i> HEALTHY VASCULAR LUMEN</strong>\n                    <p>Arterial calibers fully open. Penile blood flow unhindered.</p>\n                `;\n            }\n        }\n\n        function initReferencesGrid() {\n            const grid = document.getElementById('referencesGrid');\n            grid.innerHTML = '';\n            Object.keys(citationDB).forEach(key => {\n                const item = citationDB[key];\n                grid.innerHTML += `\n                    <div onclick=\"showCitationModal(${key})\" class=\"p-3 bg-slate-900/90 rounded-xl border border-slate-800 hover:border-brand-500/50 cursor-pointer transition space-y-1\">\n                        <div class=\"flex items-center justify-between\">\n                            <span class=\"font-bold text-brand-400\">[${key}]</span>\n                            <span class=\"text-[10px] text-slate-500\">${item.year}</span>\n                        </div>\n                        <div class=\"text-white font-bold truncate\">${item.title}</div>\n                        <div class=\"text-[10px] text-slate-400 truncate\">${item.journal}</div>\n                    </div>\n                `;\n            });\n        }\n\n        function showCitationModal(refNum) {\n            const item = citationDB[refNum];\n            if (!item) return;\n            document.getElementById('modalRefNum').innerText = `[${refNum}]`;\n            document.getElementById('modalRefTitle').innerText = item.title;\n            document.getElementById('modalRefSummary').innerText = item.summary;\n            document.getElementById('modalRefJournal').innerText = item.journal;\n            document.getElementById('modalRefPmid').innerText = item.pmid;\n            openModal('citationModal');\n        }\n\n        function openModal(id) { document.getElementById(id).classList.remove('hidden'); }\n        function closeModal(id) { document.getElementById(id).classList.add('hidden'); }\n\n        function toggleMobileMenu() {\n            document.getElementById('mobileMenu').classList.toggle('hidden');\n        }\n\n        function showToast(msg) {\n            const t = document.getElementById('toast');\n            document.getElementById('toastMsg').innerText = msg;\n            t.classList.remove('hidden');\n            setTimeout(() => { t.classList.add('hidden'); }, 3000);\n        }\n    </script>\n</body>\n</html>";
